('math_pizza_chef', 'ถาดเดียวแบ่งทั้งโต๊ะ', '{"icon":"🍽️","story":["ครอบครัวหนึ่งสั่งพิซซ่าเพียง 1 ถาด แต่ละคนอยากได้ไม่เท่ากัน","ส่วนที่เหลือเชฟจะห่อให้กลับบ้าน ต้องรู้ว่าเหลือเท่าไร"],"tip":"","context":[{"type":"table","title":"🧾 ออเดอร์ของลูกค้า","head":["ลูกค้า","สั่ง","เงื่อนไข"],"rows":[["ภูผา","1/2 ถาด","-"],["ก้อง","1/4 ถาด","-"],["นที","1/6 ถาด","-"]]},{"type":"note","text":"ข้อมูลเพิ่มเติม: ถาดพิซซ่ามีเส้นผ่านศูนย์กลาง 12 นิ้ว และราคา 299 บาท"}],"steps":[{"kind":"choice","prompt":"ข้อมูลใดไม่จำเป็นต่อการหาว่าพิซซ่าเหลือเท่าไร","skill":"analysis","points":5,"hints":[],"solution":["คำถามถามปริมาณที่เหลือ ใช้เพียงปริมาณทั้งหมด (1 ถาด) และปริมาณที่แต่ละคนสั่ง ขนาดและราคาไม่เกี่ยว"],"options":[{"text":"จำนวนถาดที่สั่ง (1 ถาด)","ok":false,"why":"ต้องใช้ 1 ถาดเป็นปริมาณทั้งหมดเพื่อหาส่วนที่เหลือ"},{"text":"ขนาดและราคาของพิซซ่า","ok":true,"why":""},{"text":"ปริมาณที่แต่ละคนสั่ง","ok":false,"why":"ต้องใช้ปริมาณที่สั่งเพื่อหาผลรวม"}],"answer":1},{"kind":"choice","prompt":"ใครได้พิซซ่ามากที่สุด","skill":"analysis","points":10,"hints":["แปลงทุกออเดอร์ให้มีตัวส่วน 12"],"solution":["ภูผา: 1/2 = 6/12","ก้อง: 1/4 = 3/12","นที: 1/6 = 2/12"],"options":[{"text":"ก้อง","ok":false,"why":"ก้อง ได้ 3/12 ถาด น้อยกว่าภูผาที่ได้ 6/12 ถาด"},{"text":"นที","ok":false,"why":"นที ได้ 2/12 ถาด น้อยกว่าภูผาที่ได้ 6/12 ถาด"},{"text":"ภูผา","ok":true,"why":"ภูผา ได้ 6/12 ถาด น้อยกว่าภูผาที่ได้ 6/12 ถาด"}],"answer":2},{"kind":"fraction","prompt":"ลูกค้าทุกคนสั่งพิซซ่ารวมกันกี่ถาด","skill":"analysis","points":10,"hints":["ตัวส่วนไม่เท่ากัน ต้องหาเศษส่วนที่เท่ากันซึ่งมีตัวส่วนเป็น 12 ก่อน","แปลงทีละออเดอร์ เช่น 1/2 = 6/12 แล้วบวกเฉพาะตัวเศษ"],"solution":["ทำตัวส่วนให้เท่ากันเป็น 12: 1/2 = 6/12, 1/4 = 3/12, 1/6 = 2/12","บวกตัวเศษ: 6 + 3 + 2 = 11 จึงได้ 11/12 = 11/12 ถาด"],"answer":{"n":11,"d":12},"unit":"ถาด","mistakes":[{"value":{"n":1,"d":4},"why":"ห้ามบวกตัวส่วนเข้าด้วยกัน ต้องทำตัวส่วนให้เท่ากันก่อน แล้วบวกเฉพาะตัวเศษ"}]},{"kind":"fraction","prompt":"เหลือพิซซ่าห่อกลับบ้านกี่ถาด","skill":"