('math_pizza_chef', 'ออเดอร์มีเงื่อนไข', '{"icon":"📋","story":["มีลูกค้า 4 คน บางคนมีเงื่อนไขพิเศษ ร้านมีพิซซ่า 3 ถาด","วางแผนให้ใช้ถาดน้อยที่สุดโดยทำตามเงื่อนไขทุกข้อ"],"context":[{"type":"table","title":"🧾 ออเดอร์ของลูกค้า","head":["ลูกค้า","สั่ง","เงื่อนไข"],"rows":[["ก้อง","1/6 ถาด","ขอถาดแยก ห้ามปนกับคนอื่น"],["ภูผา","1/4 ถาด","ต้องได้จากถาดเดียวกับขิง"],["ขิง","5/12 ถาด","ต้องได้จากถาดเดียวกับภูผา"],["มะปราง","1/12 ถาด","-"]]}],"steps":[{"kind":"fraction","prompt":"ลูกค้าทุกคนสั่งพิซซ่ารวมกันกี่ถาด","skill":"analysis","points":10,"hints":["ตัวส่วนไม่เท่ากัน ต้องหาเศษส่วนที่เท่ากันซึ่งมีตัวส่วนเป็น 12 ก่อน","แปลงทีละออเดอร์ เช่น 1/6 = 2/12 แล้วบวกเฉพาะตัวเศษ"],"solution":["ทำตัวส่วนให้เท่ากันเป็น 12: 1/6 = 2/12, 1/4 = 3/12, 5/12 = 5/12, 1/12 = 1/12","บวกตัวเศษ: 2 + 3 + 5 + 1 = 11 จึงได้ 11/12 = 11/12 ถาด"],"answer":{"n":11,"d":12},"unit":"ถาด","mistakes":[{"value":{"n":4,"d":17},"why":"ห้ามบวกตัวส่วนเข้าด้วยกัน ต้องทำตัวส่วนให้เท่ากันก่อน แล้วบวกเฉพาะตัวเศษ"}]},{"kind":"choice","prompt":"เปรียบเทียบแผนการตัด: แผนใดแบ่งได้พอดีทุกออเดอร์และหั่นชิ้นน้อยที่สุด","skill":"planning","points":10,"hints":["จำนวนชิ้นต่อถาดต้องหารด้วยตัวส่วนของทุกออเดอร์ได้ลงตัว","ตัวส่วนของออเดอร์คือ 6, 4, 12 หาจำนวนที่น้อยที่สุดในตัวเลือกที่ทุกตัวหารลงตัว"],"solution":["ตัวส่วนของออเดอร์: 6, 4, 12","12 เป็นจำนวนชิ้นที่น้อยที่สุดในตัวเลือกที่ทุกตัวส่วนหารลงตัว จึงได้ชิ้นใหญ่ที่สุด"],"options":[{"text":"ตัดถาดละ 2 ชิ้น (ชิ้นละ 1/2 ถาด)","value":2,"ok":false,"why":"2 หารด้วย 6 ไม่ลงตัว จึงแบ่ง 1/6 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 4 ชิ้น (ชิ้นละ 1/4 ถาด)","value":4,"ok":false,"why":"4 หารด้วย 6 ไม่ลงตัว จึงแบ่ง 1/6 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 8 ชิ้น (ชิ้นละ 1/8 ถาด)","value":8,"ok":false,"why":"8 หารด้วย 6 ไม่ลงตัว จึงแบ่ง 1/6 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 12 ชิ้น (ชิ้นละ 1/12 ถาด)","value":12,"ok":true,"why":"แบ่งได้พอดี แต่ชิ้นเล็กเกินจำเป็น 1 ชิ้นแบบ 12 ชิ้นเท่ากับ 1 ชิ้นแบบนี้ ต้องหั่นและหยิบหลายชิ้นขึ้น"},{"text":"ตัดถาดละ 16 ชิ้น (ชิ้นละ 1/16 ถาด)","value":16,"ok":false,"why":"16 หารด้วย 6 ไม่ลงตัว จึงแบ่ง 1/6 ถาดให้พอดีไม่ได้"}],"answer":3,"keepOrder":true,"store":"cut"},{"kind":"number","prompt":"ภายใต้เงื่อนไขทั้งหมด ต้องใช้พิซซ่าอย่างน้อยกี่ถาด","skill":"planning","points":15,"hints":["ก้องใช้ 1 ถาดเต็ม คนอื่นใช้ส่วนที่เหลือไม่ได้","ภูผากับขิงอยู่ถาดเดียวกัน ที่ว่างในถาดนั้นให้คนอื่นใช้ได้"],"solution":["ตัดถาดละ 12 ชิ้น: ก้อง 2, ภูผา 3, ขิง 5, มะปราง 1 ชิ้น","ก้อง ใช้ถาดแยก 1 ถาด","ภูผา+ขิง = 8 ชิ้น อยู่ถาดเดียวกัน เหลือที่ว่าง 4 ชิ้น","คนอื่นรวม 1 ชิ้น ใส่ในที่ว่าง 4 ชิ้นก่อน ส่วนที่เกินต้องใช้ถาดใหม่","รวมใช้อย่างน้อย 2 ถาด (ผลรวมทั้งหมด 11/12 ถาด แต่เงื่อนไขทำให้ต้องใช้ถาดมากขึ้น)"],"answer":2,"unit":"ถาด","mistakes":[{"value":1,"why":"1 ถาดพอเมื่อไม่มีเงื่อนไข แต่ถาดของก้องใช้ร่วมกับคนอื่นไม่ได้"}]},{"kind":"pizza","prompt":"จัดชิ้นพิซซ่าให้ครบทุกออเดอร์ ตามเงื่อนไข โดยใช้ถาดน้อยที่สุด (มีให้ใช้ 3 ถาด)","skill":"final","points":20,"hints":["เลือกชื่อลูกค้าก่อน แล้วแตะชิ้นพิซซ่าเพื่อมอบให้ แตะซ้ำเพื่อยกเลิก","แปลงออเดอร์เป็นจำนวนชิ้น เช่น 1/6 ถาด = 2/12 ถาด คือ 2 ชิ้น"],"solution":["ตัดถาดละ 12 ชิ้น 1 ชิ้น = 1/12 ถาด","ก้อง: 1/6 = 2/12 ถาด จึงได้ 2 ชิ้น","ภูผา: 1/4 = 3/12 ถาด จึงได้ 3 ชิ้น","ขิง: 5/12 = 5/12 ถาด จึงได้ 5 ชิ้น","มะปราง: 1/12 = 1/12 ถาด จึงได้ 1 ชิ้น","รวม 11 ชิ้น จาก 24 ชิ้นใน 2 ถาด เหลือ 13 ชิ้น","ภูผา กับ ขิง ใช้ 8 ชิ้น ไม่เกิน 12 ชิ้น จึงวางในถาดเดียวกันได้"],"orders":[{"name":"ก้อง","f":{"n":1,"d":6}},{"name":"ภูผา","f":{"n":1,"d":4}},{"name":"ขิง","f":{"n":5,"d":12}},{"name":"มะปราง","f":{"n":1,"d":12}}],"trays":3,"defaultCut":12,"together":[1,2],"own":0,"minTrays":2}]}', 'hard', 17),
('math_pizza_chef', 'ออเดอร์ล้นร้าน!', '{"icon":"🍕","story":["ร้านได้รับออเดอร์ 4 รายการ เชฟมีพิซซ่าอยู่ 1 ถาด","คำนวณก่อนว่าพิซซ่าพอหรือไม่ แล้ววางแผนตัดและจัดชิ้นให้ตรงทุกออเดอร์"],"tip":"","context":[{"type":"table","title":"🧾 ออเดอร์ของลูกค้า","head":["ลูกค้า","สั่ง","เงื่อนไข"],"rows":[["แพรว","1/2 ถาด","-"],["นที","1/4 ถาด","-"],["น้ำใส","5/16 ถาด","-"],["ขิง","7/8 ถาด","-"]]}],"steps":[{"kind":"fraction","prompt":"ลูกค้าทุกคนสั่งพิซซ่ารวมกันกี่ถาด","skill":"analysis","points":10,"hints":["ตัวส่วนไม่เท่ากัน ต้องหาเศษส่วนที่เท่ากันซึ่งมีตัวส่วนเป็น 16 ก่อน","แปลงทีละออเดอร์ เช่น 1/2 = 8/16 แล้วบวกเฉพาะตัวเศษ"],"solution":["ทำตัวส่วนให้เท่ากันเป็น 16: 1/2 = 8/16, 1/4 = 4/16, 5/16 = 5/16, 7/8 = 14/16","บวกตัวเศษ: 8 + 4 + 5 + 14 = 31 จึงได้ 31/16 = 1 15/16 ถาด"],"answer":{"n":31,"d":16},"unit":"ถาด","mistakes":[{"value":{"n":7,"d":15},"why":"ห้ามบวกตัวส่วนเข้าด้วยกัน ต้องทำตัวส่วนให้เท่ากันก่อน แล้วบวกเฉพาะตัวเศษ"}]},{"kind":"choice","prompt":"เชฟมีพิซซ่า 1 ถาด เพียงพอสำหรับทุกออเดอร์หรือไม่","skill":"analysis","points":10,"hints":["เขียน 1 ถาดเป็นเศษส่วนที่มีตัวส่วนเดียวกับผลรวม"],"solution":["1 ถาด = 16/16 ส่วนออเดอร์รวม = 31/16"],"options":[{"text":"พอ และยังมีพิซซ่าเหลือ","ok":false,"why":"ยังไม่ใช่ ลองเทียบ: 1 ถาด = 16/16 ส่วนออเดอร์รวม = 31/16"},{"text":"พอดี ไม่เหลือเลย","ok":false,"why":"ยังไม่ใช่ ลองเทียบ: 1 ถาด = 16/16 ส่วนออเดอร์รวม = 31/16"},{"text":"ไม่พอ ต้องอบเพิ่ม","ok":true,"why":"ยังไม่ใช่ ลองเทียบ: 1 ถาด = 16/16 ส่วนออเดอร์รวม = 31/16"}],"answer":2,"keepOrder":true},{"kind":"fraction","prompt":"พิซซ่าขาดอยู่กี่ถาด","skill":"calculation","points":10,"hints":["นำผลรวมออเดอร์ 1 15/16 ลบด้วย 1","1 = 16/16"],"solution":["1 15/16 − 1 = 31/16 − 16/16 = 15/16 ถาด"],"answer":{"n":15,"d":16},"unit":"ถาด"},{"kind":"number","prompt":"เชฟต้องอบพิซซ่าเพิ่มอย่างน้อยกี่ถาด (นับเป็นถาดเต็ม)","skill":"planning","points":10,"hints":["ร้านอบได้ทีละถาดเต็ม ถ้าขาดไม่ถึง 1 ถาดก็ต้องอบ 1 ถาด"],"solution":["ขาด 15/16 ถาด ต้องปัดขึ้นเป็นถาดเต็ม จึงอบเพิ่ม 1 ถาด"],"answer