('math_pizza_chef', 'ออเดอร์มีเงื่อนไข', '{"icon":"📋","story":["มีลูกค้า 4 คน บางคนมีเงื่อนไขพิเศษ ร้านมีพิซซ่า 4 ถาด","วางแผนให้ใช้ถาดน้อยที่สุดโดยทำตามเงื่อนไขทุกข้อ"],"context":[{"type":"table","title":"🧾 ออเดอร์ของลูกค้า","head":["ลูกค้า","สั่ง","เงื่อนไข"],"rows":[["ข้าวหอม","1/3 ถาด","ขอถาดแยก ห้ามปนกับคนอื่น"],["นที","1/6 ถาด","-"],["ขิง","1/12 ถาด","ต้องได้จากถาดเดียวกับต้นกล้า"],["ต้นกล้า","5/6 ถาด","ต้องได้จากถาดเดียวกับขิง"]]}],"steps":[{"kind":"fraction","prompt":"ลูกค้าทุกคนสั่งพิซซ่ารวมกันกี่ถาด","skill":"analysis","points":10,"hints":["ตัวส่วนไม่เท่ากัน ต้องหาเศษส่วนที่เท่ากันซึ่งมีตัวส่วนเป็น 12 ก่อน","แปลงทีละออเดอร์ เช่น 1/3 = 4/12 แล้วบวกเฉพาะตัวเศษ"],"solution":["ทำตัวส่วนให้เท่ากันเป็น 12: 1/3 = 4/12, 1/6 = 2/12, 1/12 = 1/12, 5/6 = 10/12","บวกตัวเศษ: 4 + 2 + 1 + 10 = 17 จึงได้ 17/12 = 1 5/12 ถาด"],"answer":{"n":17,"d":12},"unit":"ถาด","mistakes":[{"value":{"n":8,"d":27},"why":"ห้ามบวกตัวส่วนเข้าด้วยกัน ต้องทำตัวส่วนให้เท่ากันก่อน แล้วบวกเฉพาะตัวเศษ"}]},{"kind":"choice","prompt":"เปรียบเทียบแผนการตัด: แผนใดแบ่งได้พอดีทุกออเดอร์และหั่นชิ้นน้อยที่สุด","skill":"planning","points":10,"hints":["จำนวนชิ้นต่อถาดต้องหารด้วยตัวส่วนของทุกออเดอร์ได้ลงตัว","ตัวส่วนของออเดอร์คือ 3, 6, 12 หาจำนวนที่น้อยที่สุดในตัวเลือกที่ทุกตัวหารลงตัว"],"solution":["ตัวส่วนของออเดอร์: 3, 6, 12","12 เป็นจำนวนชิ้นที่น้อยที่สุดในตัวเลือกที่ทุกตัวส่วนหารลงตัว จึงได้ชิ้นใหญ่ที่สุด"],"options":[{"text":"ตัดถาดละ 2 ชิ้น (ชิ้นละ 1/2 ถาด)","value":2,"ok":false,"why":"2 หารด้วย 3 ไม่ลงตัว จึงแบ่ง 1/3 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 4 ชิ้น (ชิ้นละ 1/4 ถาด)","value":4,"ok":false,"why":"4 หารด้วย 3 ไม่ลงตัว จึงแบ่ง 1/3 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 8 ชิ้น (ชิ้นละ 1/8 ถาด)","value":8,"ok":false,"why":"8 หารด้วย 3 ไม่ลงตัว จึงแบ่ง 1/3 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 12 ชิ้น (ชิ้นละ 1/12 ถาด)","value":12,"ok":true,"why":"แบ่งได้พอดี แต่ชิ้นเล็กเกินจำเป็น 1 ชิ้นแบบ 12 ชิ้นเท่ากับ 1 ชิ้นแบบนี้ ต้องหั่นและหยิบหลายชิ้นขึ้น"},{"text":"ตัดถาดละ 16 ชิ้น (ชิ้นละ 1/16 ถาด)","value":1