('math_pizza_chef', 'คืนวันศุกร์ที่ร้านพิซซ่า', '{"icon":"🍕","story":["ร้านได้รับออเดอร์ 4 รายการ เชฟมีพิซซ่าอยู่ 2 ถาด","คำนวณก่อนว่าพิซซ่าพอหรือไม่ แล้ววางแผนตัดและจัดชิ้นให้ตรงทุกออเดอร์"],"tip":"","context":[{"type":"table","title":"🧾 ออเดอร์ของลูกค้า","head":["ลูกค้า","สั่ง","เงื่อนไข"],"rows":[["ก้อง","1/4 ถาด","-"],["ต้นกล้า","1/3 ถาด","-"],["ข้าวหอม","5/12 ถาด","-"],["ภูผา","1/6 ถาด","-"]]}],"steps":[{"kind":"fraction","prompt":"ลูกค้าทุกคนสั่งพิซซ่ารวมกันกี่ถาด","skill":"analysis","points":10,"hints":["ตัวส่วนไม่เท่ากัน ต้องหาเศษส่วนที่เท่ากันซึ่งมีตัวส่วนเป็น 12 ก่อน","แปลงทีละออเดอร์ เช่น 1/4 = 3/12 แล้วบวกเฉพาะตัวเศษ"],"solution":["ทำตัวส่วนให้เท่ากันเป็น 12: 1/4 = 3/12, 1/3 = 4/12, 5/12 = 5/12, 1/6 = 2/12","บวกตัวเศษ: 3 + 4 + 5 + 2 = 14 จึงได้ 14/12 = 1 1/6 ถาด"],"answer":{"n":7,"d":6},"unit":"ถาด","mistakes":[{"value":{"n":8,"d":25},"why":"ห้ามบวกตัวส่วนเข้าด้วยกัน ต้องทำตัวส่วนให้เท่ากันก่อน แล้วบวกเฉพาะตัวเศษ"}]},{"kind":"choice","prompt":"เชฟมีพิซซ่า 2 ถาด เพียงพอสำหรับทุกออเดอร์หรือไม่","skill":"analysis","points":10,"hints":["เขียน 2 ถาดเป็นเศษส่วนที่มีตัวส่วนเดียวกับผลรวม"],"solution":["2 ถาด = 24/12 ส่วนออเดอร์รวม = 14/12"],"options":[{"text":"พอ และยังมีพิซซ่าเหลือ","ok":true,"why":"ยังไม่ใช่ ลองเทียบ: 2 ถาด = 24/12 ส่วนออเดอร์รวม = 14/12"},{"text":"พอดี ไม่เหลือเลย","ok":false,"why":"ยังไม่ใช่ ลองเทียบ: 2 ถาด = 24/12 ส่วนออเดอร์รวม = 14/12"},{"text":"ไม่พอ ต้องอบเพิ่ม","ok":false,"why":"ยังไม่ใช่ ลองเทียบ: 2 ถาด = 24/12 ส่วนออเดอร์รวม = 14/12"}],"answer":0,"keepOrder":true},{"kind":"fraction","prompt":"หลังส่งทุกออเดอร์ จะเหลือพิซซ่ากี่ถาด","skill":"calculation","points":10,"hints":["นำ 2 ลบด้วย 1 1/6","2 = 12/6"],"solution":["2 − 1 1/6 = 12/6 − 7/6 = 5/6 ถาด"],"answer":{"n":5,"d":6},"unit":"ถาด"},{"kind":"choice","prompt":"ควรตัดพิซซ่าถาดละกี่ชิ้น จึงแบ่งได้พอดีทุกออเดอร์และชิ้นใหญ่ที่สุด","skill":"planning","points":10,"hints":["จำนวนชิ้นต่อถาดต้องหารด้วยตัวส่วนของทุกออเดอร์ได้ลงตัว","ตัวส่วนของออเดอร์คือ 4, 3, 12, 6 หาจำนวนที่น้อยที่สุดในตั