('math_pizza_chef', 'ใครหิวที่สุด?', '{"icon":"🧑‍🍳","story":["ลูกค้า 4 คนสั่งพิซซ่าคนละไม่เท่ากัน ร้านมีพิซซ่า 3 ถาด","เปรียบเทียบออเดอร์ แล้วจัดชิ้นโดยใช้ถาดให้น้อยที่สุด ถาดที่ไม่ได้แตะจะเก็บไว้ขายต่อได้"],"tip":"","context":[{"type":"table","title":"🧾 ออเดอร์ของลูกค้า","head":["ลูกค้า","สั่ง","เงื่อนไข"],"rows":[["น้ำใส","1/8 ถาด","-"],["ก้อง","1/2 ถาด","-"],["พลอย","1/4 ถาด","-"],["ธาม","3/8 ถาด","-"]]}],"steps":[{"kind":"choice","prompt":"ลูกค้าคนใดสั่งพิซซ่ามากที่สุด","skill":"analysis","points":10,"hints":["ทำตัวส่วนให้เท่ากันเป็น 8 แล้วเทียบตัวเศษ"],"solution":["น้ำใส: 1/8 = 1/8","ก้อง: 1/2 = 4/8","พลอย: 1/4 = 2/8","ธาม: 3/8 = 3/8"],"options":[{"text":"น้ำใส (1/8 ถาด)","ok":false,"why":"น้ำใส สั่ง 1/8 ถาด แต่ก้องสั่ง 4/8 ถาด"},{"text":"พลอย (1/4 ถาด)","ok":false,"why":"พลอย สั่ง 2/8 ถาด แต่ก้องสั่ง 4/8 ถาด"},{"text":"ธาม (3/8 ถาด)","ok":false,"why":"ธาม สั่ง 3/8 ถาด แต่ก้องสั่ง 4/8 ถาด"},{"text":"ก้อง (1/2 ถาด)","ok":true,"why":"ก้อง สั่ง 4/8 ถาด แต่ก้องสั่ง 4/8 ถาด"}],"answer":3},{"kind":"fraction","prompt":"ก้องสั่งมากกว่าน้ำใสกี่ถาด","skill":"calculation","points":10,"hints":["ลบเศษส่วน: 1/2 − 1/8","ทำตัวส่วนให้เท่ากันก่อน: 4/8 − 1/8"],"solution":["4/8 − 1/8 = 3/8 ถาด"],"answer":{"n":3,"d":8},"unit":"ถาด","mistakes":[{"value":{"n":0,"d":1},"why":"ห้ามลบตัวส่วนกัน ทำตัวส่วนให้เท่ากันก่อนแล้วลบเฉพาะตัวเศษ"}]},{"kind":"fraction","prompt":"ลูกค้าทุกคนสั่งพิซซ่ารวมกันกี่ถาด","skill":"analysis","points":10,"hints":["ตัวส่วนไม่เท่ากัน ต้องหาเศษส่วนที่เท่ากันซึ่งมีตัวส่วนเป็น 8 ก่อน","แปลงทีละออเดอร์ เช่น 1/8 = 1/8 แล้วบวกเฉพาะตัวเศษ"],"solution":["ทำตัวส่วนให้เท่ากันเป็น 8: 1/8 = 1/8, 1/2 = 4/8, 1/4 = 2/8, 3/8 = 3/8","บวกตัวเศษ: 1 + 4 + 2 + 3 = 10 จึงได้ 10/8 = 1 1/4 ถาด"],"answer":{"n":5,"d":4},"unit":"ถาด","mistakes":[{"value":{"n":3,"d":11},"why":"ห้ามบวกตัวส่วนเข้าด้วยกัน ต้องทำตัวส่วนให้เท่ากันก่อน แล้วบวกเฉพาะตัวเศษ"}]},{"kind":"choice","prompt":"ควรตัดพิซซ่าถาดละกี่ชิ้น จึงแบ่งได้พอดีทุกออเดอร์และชิ้นใหญ่ที่สุด","skill":"planning","points":10,"hints":["จำ