('math_pizza_chef', 'คืนวันศุกร์ที่ร้านพิซซ่า', '{"icon":"🍕","story":["ร้านได้รับออเดอร์ 4 รายการ เชฟมีพิซซ่าอยู่ 2 ถาด","คำนวณก่อนว่าพิซซ่าพอหรือไม่ แล้ววางแผนตัดและจัดชิ้นให้ตรงทุกออเดอร์"],"tip":"","context":[{"type":"table","title":"🧾 ออเดอร์ของลูกค้า","head":["ลูกค้า","สั่ง","เงื่อนไข"],"rows":[["ข้าวหอม","1/4 ถาด","-"],["แพรว","5/8 ถาด","-"],["น้ำใส","1/8 ถาด","-"],["ขิง","7/8 ถาด","-"]]}],"steps":[{"kind":"fraction","prompt":"ลูกค้าทุกคนสั่งพิซซ่ารวมกันกี่ถาด","skill":"analysis","points":10,"hints":["ตัวส่วนไม่เท่ากัน ต้องหาเศษส่วนที่เท่ากันซึ่งมีตัวส่วนเป็น 8 ก่อน","แปลงทีละออเดอร์ เช่น 1/4 = 2/8 แล้วบวกเฉพาะตัวเศษ"],"solution":["ทำตัวส่วนให้เท่ากันเป็น 8: 1/4 = 2/8, 5/8 = 5/8, 1/8 = 1/8, 7/8 = 7/8","บวกตัวเศษ: 2 + 5 + 1 + 7 = 15 จึงได้ 15/8 = 1 7/8 ถาด"],"answer":{"n":15,"d":8},"unit":"ถาด","mistakes":[{"value":{"n":1,"d":2},"why":"ห้ามบวกตัวส่วนเข้าด้วยกัน ต้องทำตัวส่วนให้เท่ากันก่อน แล้วบวกเฉพาะตัวเศษ"}]},{"kind":"choice","prompt":"เชฟมีพิซซ่า 2 ถาด เพียงพอสำหรับทุกออเดอร์หรือไม่","skill":"analysis","points":10,"hints":["เขียน 2 ถาดเป็นเศษส่วนที่มีตัวส่วนเดียวกับผลรวม"],"solution":["2 ถาด = 16/8 ส่วนออเดอร์รวม = 15/8"],"options":[{"text":"พอ และยังมีพิซซ่าเหลือ","ok":true,"why":"ยังไม่ใช่ ลองเทียบ: 2 ถาด = 16/8 ส่วนออเดอร์รวม = 15/8"},{"text":"พอดี ไม่เหลือเลย","ok":false,"why":"ยังไม่ใช่ ลองเทียบ: 2 ถาด = 16/8 ส่วนออเดอร์รวม = 15/8"},{"text":"ไม่พอ ต้องอบเพิ่ม","ok":false,"why":"ยังไม่ใช่ ลองเทียบ: 2 ถาด = 16/8 ส่วนออเดอร์รวม = 15/8"}],"answer":0,"keepOrder":true},{"kind":"fraction","prompt":"หลังส่งทุกออเดอร์ จะเหลือพิซซ่ากี่ถาด","skill":"calculation","points":10,"hints":["นำ 2 ลบด้วย 1 7/8","2 = 16/8"],"solution":["2 − 1 7/8 = 16/8 − 15/8 = 1/8 ถาด"],"answer":{"n":1,"d":8},"unit":"ถาด"},{"kind":"choice","prompt":"ควรตัดพิซซ่าถาดละกี่ชิ้น จึงแบ่งได้พอดีทุกออเดอร์และชิ้นใหญ่ที่สุด","skill":"planning","points":10,"hints":["จำนวนชิ้นต่อถาดต้องหารด้วยตัวส่วนของทุกออเดอร์ได้ลงตัว","ตัวส่วนของออเดอร์คือ 4, 8 หาจำนวนที่น้อยที่สุดในตัวเลือกที่ทุกตัวหารลงตัว"],"