('math_pizza_chef', 'แป้งหมด! ห้ามขาดห้ามเกิน', '{"icon":"🏆","story":["วันนี้แป้งเหลือพอทำพิซซ่าได้แค่ 2 ถาดเท่านั้น","ต้องจัดทุกออเดอร์ให้ครบ ห้ามขาดและห้ามเกิน และอธิบายได้ว่าทำไมแผนนี้ใช้ได้"],"context":[{"type":"table","title":"🧾 ออเดอร์ของลูกค้า","head":["ลูกค้า","สั่ง","เงื่อนไข"],"rows":[["ขิง","9/16 ถาด","-"],["ภูผา","1/4 ถาด","ต้องได้จากถาดเดียวกับน้ำใส"],["น้ำใส","5/16 ถาด","ต้องได้จากถาดเดียวกับภูผา"],["ต้นกล้า","7/8 ถาด","-"]]}],"steps":[{"kind":"fraction","prompt":"ลูกค้าทุกคนสั่งพิซซ่ารวมกันกี่ถาด","skill":"analysis","points":10,"hints":["ตัวส่วนไม่เท่ากัน ต้องหาเศษส่วนที่เท่ากันซึ่งมีตัวส่วนเป็น 16 ก่อน","แปลงทีละออเดอร์ เช่น 9/16 = 9/16 แล้วบวกเฉพาะตัวเศษ"],"solution":["ทำตัวส่วนให้เท่ากันเป็น 16: 9/16 = 9/16, 1/4 = 4/16, 5/16 = 5/16, 7/8 = 14/16","บวกตัวเศษ: 9 + 4 + 5 + 14 = 32 จึงได้ 32/16 = 2 ถาด"],"answer":{"n":2,"d":1},"unit":"ถาด","mistakes":[{"value":{"n":1,"d":2},"why":"ห้ามบวกตัวส่วนเข้าด้วยกัน ต้องทำตัวส่วนให้เท่ากันก่อน แล้วบวกเฉพาะตัวเศษ"}]},{"kind":"choice","prompt":"พิซซ่า 2 ถาด เพียงพอหรือไม่","skill":"analysis","points":10,"hints":[],"solution":["ออเดอร์รวม = 2 ถาด = 2 ถาด พอดี"],"options":[{"text":"พอดี ไม่ขาดไม่เกิน","ok":true,"why":""},{"text":"พอ และยังเหลือ","ok":false,"why":"ออเดอร์รวม 2 ถาด เท่ากับพิซซ่าที่มี จึงไม่เหลือ"},{"text":"ไม่พอ","ok":false,"why":"ออเดอร์รวม 2 ถาด ไม่มากกว่า 2 ถาด"}],"answer":0,"keepOrder":true},{"kind":"choice","prompt":"ควรตัดพิซซ่าถาดละกี่ชิ้น จึงแบ่งได้พอดีทุกออเดอร์และชิ้นใหญ่ที่สุด","skill":"planning","points":10,"hints":["จำนวนชิ้นต่อถาดต้องหารด้วยตัวส่วนของทุกออเดอร์ได้ลงตัว","ตัวส่วนของออเดอร์คือ 16, 4, 8 หาจำนวนที่น้อยที่สุดในตัวเลือกที่ทุกตัวหารลงตัว"],"solution":["ตัวส่วนของออเดอร์: 16, 4, 8","16 เป็นจำนวนชิ้นที่น้อยที่สุดในตัวเลือกที่ทุกตัวส่วนหารลงตัว จึงได้ชิ้นใหญ่ที่สุด"],"options":[{"text":"ตัดถาดละ 2 ชิ้น (ชิ้นละ 1/2 ถาด)","value":2,"ok":false,"why":"2 หารด้วย 16 ไม่ลงตัว จึงแบ่ง 9/16 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 4 ชิ้น (ชิ้นละ 1/4 ถาด)","value":4,"ok":false,"why":"4 หารด้วย 16 ไม่ลงตัว จึงแบ่ง 9/16 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 8 ชิ้น (ชิ้นละ 1/8 ถาด)","value":8,"ok":false,"why":"8 หารด้วย 16 ไม่ลงตัว จึงแบ่ง 9/16 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 12 ชิ้น (ชิ้นละ 1/12 ถาด)","value":12,"ok":false,"why":"12 หารด้วย 16 ไม่ลงตัว จึงแบ่ง 9/16 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 16 ชิ้น (ชิ้นละ 1/16 ถาด)","value":16,"ok":true,"why":"แบ่งได้พอดี แต่ชิ้นเล็กเกินจำเป็น 1 ชิ้นแบบ 16 ชิ้นเท่ากับ 1 ชิ้นแบบนี้ ต้องหั่นและหยิบหลายชิ้นขึ้น"}],"answer":4,"keepOrder":true,"store":"cut"},{"kind":"choice","prompt":"เหตุผลใดอธิบายได้ถูกต้องว่าแผนนี้จัดได้ครบโดยไม่ขาดไม่เกิน","skill":"planning","points":10,"hints":[],"solution":["ตัดถาดละ 16 ชิ้น: ขิง 9 + ภูผา 4 + น้ำใส 5 + ต้นกล้า 14 = 32 ชิ้น = 2 ถาด","ภูผา+น้ำใส = 9 ≤ 16 ชิ้น วางถาดเดียวกันได้"],"options":[{"text":"เพราะทุกตัวส่วนหาร 16 ลงตัว","ok":false,"why":"เป็นเพียงเหตุผลว่าตัดชิ้นได้พอดี ยังไม่ได้แสดงว่าปริมาณรวมพอดีและเงื่อนไขถาดเดียวกันทำได้"},{"text":"แปลงเป็นชิ้นละ 1/16 ทุกออเดอร์รวมกันได้ 32 ชิ้น เท่ากับ 2 ถาดพอดี และภูผากับน้ำใสใช้ 9 ชิ้น ไม่เกินถาดเดียว","ok":true,"why":""},{"text":"เพราะตัวเศษรวมกันได้ 22 ซึ่งมากพอ","ok":false,"why":"บวกตัวเศษที่ตัวส่วนต่างกันโดยตรงไม่ได้ ต้องทำตัวส่วนให้เท่ากันก่อน"},{"text":"เพราะลูกค้าทุกคนสั่งไม่ถึง 1 ถาด จึงใช้ไม่เกิน 2 ถาดแน่นอน","ok":false,"why":"ลูกค้า 4 คนที่สั่งคนละไม่ถึง 1 ถาด อาจรวมกันเกิน 2 ถาดได้ ต้องหาผลรวมจริง"}],"answer":1},{"kind":"pizza","prompt":"จัดชิ้นพิซซ่าให้ลูกค้าแต่ละคนตรงตามออเดอร์ (มี 2 ถาด)","skill":"final","points":20,"hints":["เลือกชื่อลูกค้าก่อน แล้วแตะชิ้นพิซซ่าเพื่อมอบให้ แตะซ้ำเพื่อยกเลิก","แปลงออเดอร์เป็นจำนวนชิ้น เช่น 9/16 ถาด = 9/16 ถาด คือ 9 ชิ้น"],"solution":["ตัดถาดละ 16 ชิ้น 1 ชิ้น = 1/16 ถาด","ขิง: 9/16 = 9/16 ถาด จึงได้ 9 ชิ้น","ภูผา: 1/4 = 4/16 ถาด จึงได้ 4 ชิ้น","น้ำใส: 5/16 = 5/16 ถาด จึงได้ 5 ชิ้น","ต้นกล้า: 7/8 = 14/16 ถาด จึงได้ 14 ชิ้น","รวม 32 ชิ้น จาก 32 ชิ้นใน 2 ถาด เหลือ 0 ชิ้น","ภูผา กับ น้ำใส ใช้ 9 ชิ้น ไม่เกิน 16 ชิ้น จึงวางในถาดเดียวกันได้"],"orders":[{"name":"ขิง","f":{"n":9,"d":16}},{"name":"ภูผา","f":{"n":1,"d":4}},{"name":"น้ำใส","f":{"n":5,"d":16}},{"name":"ต้นกล้า","f":{"n":7,"d":8}}],"trays":2,"defaultCut":16,"together":[1,2],"own":null,"minTrays":null}]}', 'challenge', 25),
('math_pizza_chef', 'ออเดอร์มีเงื่อนไข', '{"icon":"📋","story":["มีลูกค้า 5 คน บางคนมีเงื่อนไขพิเศษ ร้านมีพิซซ่า 5 ถาด","วางแผนให้ใช้ถาดน้อยที่สุดโดยทำตามเงื่อนไขทุกข้อ"],"context":[{"type":"table","title":"🧾 ออเดอร์ของลูกค้า","head":["ลูกค้า","สั่ง","เงื่อนไข"],"rows":[["ต้นกล้า","7/12 ถาด","-"],["ข้าวหอม","5/6 ถาด","-"],["นที","1/3 ถาด","ต้องได้จากถาดเดียวกับภูผา"],["ธาม","2/3 ถาด","ขอถาดแยก ห้ามปนกับคนอื่น"],["ภูผา","1/2 ถาด","ต้องได้จากถาดเดียวกับนที"]]}],"steps":[{"kind":"fraction","prompt":"ลูกค้าทุกคนสั่งพิซซ่ารวมกันกี่ถาด","skill":"analysis","points":10,"hints":["ตัวส่วนไม่เท่ากัน ต้องหาเศษส่วนที่เท่ากันซึ่งมีตัวส่วนเป็น 12 ก่อน","แปลงทีละออเดอร์ เช่น 7/12 = 7/12 แล้วบวกเฉพาะตัวเศษ"],"solution":["ทำตัวส่วนให้เท่ากันเป็น 12: 7/12 = 7/12, 5/6 = 10/12, 1/3 = 4/12, 2/3 = 8/12, 1/2 = 6/12","บวกตัวเศษ: 7 + 10 + 4 + 8 + 6 = 35 จึงได้ 35/12 = 2 11/12 ถาด"],"answer":{"n":35,"d":12},"unit":"ถาด","mistakes":[{"value":{"n":8,"d":13},"why":"ห้ามบวกตัวส่วนเข้าด้วยกัน ต้องทำตัวส่วนให้เท่ากันก่อน แล้วบวกเฉพาะตัวเศษ"}]},{"kind":"choice","prompt":"เปรียบเทียบแผนการตัด: แผนใดแบ่งได้พอดีทุกออเดอร์และหั่นชิ้นน้อยที่สุด","skill":"planning","points":10,"hints":["จำนวนชิ้นต่อถาดต้องหารด้วยตัวส่วนของทุกออเดอร์ได้ลงตัว","ตัวส่วนของออเดอร์คือ 12, 6, 3, 2 หาจำนวนที่น้อยที่สุดในตัวเลือกที่ทุกตัวหารลงตัว"],"solution":["ตัวส่วนของออเดอร์: 12, 6, 3, 2","12 เป็นจำนวนชิ้นที่น้อยที่สุดในตัวเลือกที่ทุกตัวส่วนหารลงตัว จึงได้ชิ้นใหญ่ที่สุด"],"options":[{"text":"ตัดถาดละ 2 ชิ้น (ชิ้นละ 1/2 ถาด)","value":2,"ok":false,"why":"2 หารด้วย 12 ไม่ลงตัว จึงแบ่ง 7/12 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 4 ชิ้น (ชิ้นละ 1/4 ถาด)","value":4,"ok":false,"why":"4 หารด้วย 12 ไม่ลงตัว จึงแบ่ง 7/12 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 8 ชิ้น (ชิ้นละ 1/8 ถาด)","value":8,"ok":false,"why":"8 หารด้วย 12 ไม่ลงตัว จึงแบ่ง 7/12 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 12 ชิ้น (ชิ้นละ 1/12 ถาด)","value":12,"ok":true,"why":"แบ่งได้พอดี แต่ชิ้นเล็กเกินจำเป็น 1 ชิ้นแบบ 12 ชิ้นเท่ากับ 1 ชิ้นแบบนี้ ต้องหั่นและหยิบหลายชิ้นขึ้น"},{"text":"ตัดถาดละ 16 ชิ้น (ชิ้นละ 1/16 ถาด)","value":16,"ok":false,"why":"16 หารด้วย 12 ไม่ลงตัว จึงแบ่ง 7/12 ถาดให้พอดีไม่ได้"}],"answer":3,"keepOrder":true,"store":"cut"},{"kind":"number","prompt":"ภายใต้เงื่อนไขทั้งหมด ต้องใช้พิซซ่าอย่างน้อยกี่ถาด","skill":"planning","points":15,"hints":["ธามใช้ 1 ถาดเต็ม คนอื่นใช้ส่วนที่เหลือไม่ได้","นทีกับภูผาอยู่ถาดเดียวกัน ที่ว่างในถาดนั้นให้คนอื่นใช้ได้"],"solution":["ตัดถาดละ 12 ชิ้น: ต้นกล้า 7, ข้าวหอม 10, นที 4, ธาม 8, ภูผา 6 ชิ้น","ธาม ใช้ถาดแยก 1 ถาด","นที+ภูผา = 10 ชิ้น อยู่ถาดเดียวกัน เหลือที่ว่าง 2 ชิ้น","คนอื่นรวม 17 ชิ้น ใส่ในที่ว่าง 2 ชิ้นก่อน ส่วนที่เกินต้องใช้ถาดใหม่","รวมใช้อย่างน้อย 4 ถาด (ผลรวมทั้งหมด 2 11/12 ถาด แต่เงื่อนไขทำให้ต้องใช้ถาดมากขึ้น)"],"answer":4,"unit":"ถาด","mistakes":[{"value":3,"why":"3 ถาดพอเมื่อไม่มีเงื่อนไข แต่ถาดของธามใช้ร่วมกับคนอื่นไม่ได้"}]},{"kind":"pizza","prompt":"จัดชิ้นพิซซ่าให้ครบทุกออเดอร์ ตามเงื่อนไข โดยใช้ถาดน้อยที่สุด (มีให้ใช้ 5 ถาด)","skill":"final","points":20,"hints":["เลือกชื่อลูกค้าก่อน แล้วแตะชิ้นพิซซ่าเพื่อมอบให้ แตะซ้ำเพื่อยกเลิก","แปลงออเดอร์เป็นจำนวนชิ้น เช่น 7/12 ถาด = 7/12 ถาด คือ 7 ชิ้น"],"solution":["ตัดถาดละ 12 ชิ้น 1 ชิ้น = 1/12 ถาด","ต้นกล้า: 7/12 = 7/12 ถาด จึงได้ 7 ชิ้น","ข้าวหอม: 5/6 = 10/12 ถาด จึงได้ 10 ชิ้น","นที: 1/3 = 4/12 ถาด จึงได้ 4 ชิ้น","ธาม: 2/3 = 8/12 ถาด จึงได้ 8 ชิ้น","ภูผา: 1/2 = 6/12 ถาด จึงได้ 6 ชิ้น","รวม 35 ชิ้น จาก 48 ชิ้นใน 4 ถาด เหลือ 13 ชิ้น","นที กับ ภูผา ใช้ 10 ชิ้น ไม่เกิน 12 ชิ้น จึงวางในถาดเดียวกันได้","ธาม ได้ถาดของตัวเอง 1 ถาด ส่วนที่เหลือในถาดนั้นห้ามให้คนอื่น"],"orders":[{"name":"ต้นกล้า","f":{"n":7,"d":12}},{"name":"ข้าวหอม","f":{"n":5,"d":6}},{"name":"นที","f":{"n":1,"d":3}},{"name":"ธาม","f":{"n":2,"d":3}},{"name":"ภูผา","f":{"n":1,"d":2}}],"trays":5,"defaultCut":12,"together":[2,4],"own":3,"minTrays":4}]}', 'challenge', 26),
('math_pizza_chef', 'ออเดอร์ล้นร้าน!', '{"icon":"🍕","story":["ร้านได้รับออเดอร์ 5 รายการ เชฟมีพิซซ่าอยู่ 2 ถาด","คำนวณก่อนว่าพิซซ่าพอหรือไม่ แล้ววางแผนตัดและจัดชิ้นให้ตรงทุกออเดอร์"],"tip":"","context":[{"type":"table","title":"🧾 ออเดอร์ของลูกค้า","head":["ลูกค้า","สั่ง","เงื่อนไข"],"rows":[["ข้าวหอม","3/4 ถาด","-"],["ต้นกล้า","3/8 ถาด","-"],["มะปราง","7/8 ถาด","-"],["ใบเฟิร์น","1/8 ถาด","-"],["พลอย","1/2 ถาด","-"]]}],"steps":[{"kind":"fraction","prompt":"ลูกค้าทุกคนสั่งพิซซ่ารวมกันกี่ถาด","skill":"analysis","points":10,"hints":["ตัวส่วนไม่เท่ากัน ต้องหาเศษส่วนที่เท่ากันซึ่งมีตัวส่วนเป็น 8 ก่อน","แปลงทีละออเดอร์ เช่น 3/4 = 6/8 แล้วบวกเฉพาะตัวเศษ"],"solution":["ทำตัวส่วนให้เท่ากันเป็น 8: 3/4 = 6/8, 3/8 = 3/8, 7/8 = 7/8, 1/8 = 1/8, 1/2 = 4/8","บวกตัวเศษ: 6 + 3 + 7 + 1 + 4 = 21 จึงได้ 21/8 = 2 5/8 ถาด"],"answer":{"n":21,"d":8},"unit":"ถาด","mistakes":[{"value":{"n":1,"d":2},"why":"ห้ามบวกตัวส่วนเข้าด้วยกัน ต้องทำตัวส่วนให้เท่ากันก่อน แล้วบวกเฉพาะตัวเศษ"}]},{"kind":"choice","prompt":"เชฟมีพิซซ่า 2 ถาด เพียงพอสำหรับทุกออเดอร์หรือไม่","skill":"analysis","points":10,"hints":["เขียน 2 ถาดเป็นเศษส่วนที่มีตัวส่วนเดียวกับผลรวม"],"solution":["2 ถาด = 16/8 ส่วนออเดอร์รวม = 21/8"],"options":[{"text":"พอ และยังมีพิซซ่าเหลือ","ok":false,"why":"ยังไม่ใช่ ลองเทียบ: 2 ถาด = 16/8 ส่วนออเดอร์รวม = 21/8"},{"text":"พอดี ไม่เหลือเลย","ok":false,"why":"ยังไม่ใช่ ลองเทียบ: 2 ถาด = 16/8 ส่วนออเดอร์รวม = 21/8"},{"text":"ไม่พอ ต้องอบเพิ่ม","ok":true,"why":"ยังไม่ใช่ ลองเทียบ: 2 ถาด = 16/8 ส่วนออเดอร์รวม = 21/8"}],"answer":2,"keepOrder":true},{"kind":"fraction","prompt":"พิซซ่าขาดอยู่กี่ถาด","skill":"calculation","points":10,"hints":["นำผลรวมออเดอร์ 2 5/8 ลบด้วย 2","2 = 16/8"],"solution":["2 5/8 − 2 = 21/8 − 16/8 = 5/8 ถาด"],"answer":{"n":5,"d":8},"unit":"ถาด"},{"kind":"number","prompt":"เชฟต้องอบพิซซ่าเพิ่มอย่างน้อยกี่ถาด (นับเป็นถาดเต็ม)","skill":"planning","points":10,"hints":["ร้านอบได้ทีละถาดเต็ม ถ้าขาดไม่ถึง 1 ถาดก็ต้องอบ 1 ถาด"],"solution":["ขาด 5/8 ถาด ต้องปัดขึ้นเป็นถาดเต็ม จึงอบเพิ่ม 1 ถาด"],"answer":1,"unit":"ถาด"},{"kind":"choice","prompt":"ควรตัดพิซซ่าถาดละกี่ชิ้น จึงแบ่งได้พอดีทุกออเดอร์และชิ้นใหญ่ที่สุด","skill":"planning","points":10,"hints":["จำนวนชิ้นต่อถาดต้องหารด้วยตัวส่วนของทุกออเดอร์ได้ลงตัว","ตัวส่วนของออเดอร์คือ 4, 8, 2 หาจำนวนที่น้อยที่สุดในตัวเลือกที่ทุกตัวหารลงตัว"],"solution":["ตัวส่วนของออเดอร์: 4, 8, 2","8 เป็นจำนวนชิ้นที่น้อยที่สุดในตัวเลือกที่ทุกตัวส่วนหารลงตัว จึงได้ชิ้นใหญ่ที่สุด"],"options":[{"text":"ตัดถาดละ 2 ชิ้น (ชิ้นละ 1/2 ถาด)","value":2,"ok":false,"why":"2 หารด้วย 4 ไม่ลงตัว จึงแบ่ง 3/4 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 4 ชิ้น (ชิ้นละ 1/4 ถาด)","value":4,"ok":false,"why":"4 หารด้วย 8 ไม่ลงตัว จึงแบ่ง 3/8 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 8 ชิ้น (ชิ้นละ 1/8 ถาด)","value":8,"ok":true,"why":"แบ่งได้พอดี แต่ชิ้นเล็กเกินจำเป็น 1 ชิ้นแบบ 8 ชิ้นเท่ากับ 1 ชิ้นแบบนี้ ต้องหั่นและหยิบหลายชิ้นขึ้น"},{"text":"ตัดถาดละ 12 ชิ้น (ชิ้นละ 1/12 ถาด)","value":12,"ok":false,"why":"12 หารด้วย 8 ไม่ลงตัว จึงแบ่ง 3/8 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 16 ชิ้น (ชิ้นละ 1/16 ถาด)","value":16,"ok":false,"why":"แบ่งได้พอดี แต่ชิ้นเล็กเกินจำเป็น 1 ชิ้นแบบ 8 ชิ้นเท่ากับ 2 ชิ้นแบบนี้ ต้องหั่นและหยิบหลายชิ้นขึ้น"}],"answer":2,"keepOrder":true,"store":"cut"},{"kind":"pizza","prompt":"จัดชิ้นพิซซ่าให้ลูกค้าแต่ละคนตรงตามออเดอร์ (มี 3 ถาด)","skill":"final","points":20,"hints":["เลือกชื่อลูกค้าก่อน แล้วแตะชิ้นพิซซ่าเพื่อมอบให้ แตะซ้ำเพื่อยกเลิก","แปลงออเดอร์เป็นจำนวนชิ้น เช่น 3/4 ถาด = 6/8 ถาด คือ 6 ชิ้น"],"solution":["ตัดถาดละ 8 ชิ้น 1 ชิ้น = 1/8 ถาด","ข้าวหอม: 3/4 = 6/8 ถาด จึงได้ 6 ชิ้น","ต้นกล้า: 3/8 = 3/8 ถาด จึงได้ 3 ชิ้น","มะปราง: 7/8 = 7/8 ถาด จึงได้ 7 ชิ้น","ใบเฟิร์น: 1/8 = 1/8 ถาด จึงได้ 1 ชิ้น","พลอย: 1/2 = 4/8 ถาด จึงได้ 4 ชิ้น","รวม 21 ชิ้น จาก 24 ชิ้นใน 3 ถาด เหลือ 3 ชิ้น"],"orders":[{"name":"ข้าวหอม","f":{"n":3,"d":4}},{"name":"ต้นกล้า","f":{"n":3,"d":8}},{"name":"มะปราง","f":{"n":7,"d":8}},{"name":"ใบเฟิร์น","f":{"n":1,"d":8}},{"name":"พลอย","f":{"n":1,"d":2}}],"trays":3,"defaultCut":8,"together":null,"own":null,"minTrays":null}]}', 'challenge', 27),
('math_pizza_chef', 'แป้งหมด! ห้ามขาดห้ามเกิน', '{"icon":"🏆","story":["วันนี้แป้งเหลือพอทำพิซซ่าได้แค่ 2 ถาดเท่านั้น","ต้องจัดทุกออเดอร์ให้ครบ ห้ามขาดและห้ามเกิน และอธิบายได้ว่าทำไมแผนนี้ใช้ได้"],"context":[{"type":"table","title":"🧾 ออเดอร์ของลูกค้า","head":["ลูกค้า","สั่ง","เงื่อนไข"],"rows":[["ก้อง","5/6 ถาด","-"],["น้ำใส","1/4 ถาด","-"],["ใบเฟิร์น","5/12 ถาด","ต้องได้จากถาดเดียวกับมะปราง"],["มะปราง","1/2 ถาด","ต้องได้จากถาดเดียวกับใบเฟิร์น"]]}],"steps":[{"kind":"fraction","prompt":"ลูกค้าทุกคนสั่งพิซซ่ารวมกันกี่ถาด","skill":"analysis","points":10,"hints":["ตัวส่วนไม่เท่ากัน ต้องหาเศษส่วนที่เท่ากันซึ่งมีตัวส่วนเป็น 12 ก่อน","แปลงทีละออเดอร์ เช่น 5/6 = 10/12 แล้วบวกเฉพาะตัวเศษ"],"solution":["ทำตัวส่วนให้เท่ากันเป็น 12: 5/6 = 10/12, 1/4 = 3/12, 5/12 = 5/12, 1/2 = 6/12","บวกตัวเศษ: 10 + 3 + 5 + 6 = 24 จึงได้ 24/12 = 2 ถาด"],"answer":{"n":2,"d":1},"unit":"ถาด","mistakes":[{"value":{"n":1,"d":2},"why":"ห้ามบวกตัวส่วนเข้าด้วยกัน ต้องทำตัวส่วนให้เท่ากันก่อน แล้วบวกเฉพาะตัวเศษ"}]},{"kind":"choice","prompt":"พิซซ่า 2 ถาด เพียงพอหรือไม่","skill":"analysis","points":10,"hints":[],"solution":["ออเดอร์รวม = 2 ถาด = 2 ถาด พอดี"],"options":[{"text":"พอดี ไม่ขาดไม่เกิน","ok":true,"why":""},{"text":"พอ และยังเหลือ","ok":false,"why":"ออเดอร์รวม 2 ถาด เท่ากับพิซซ่าที่มี จึงไม่เหลือ"},{"text":"ไม่พอ","ok":false,"why":"ออเดอร์รวม 2 ถาด ไม่มากกว่า 2 ถาด"}],"answer":0,"keepOrder":true},{"kind":"choice","prompt":"ควรตัดพิซซ่าถาดละกี่ชิ้น จึงแบ่งได้พอดีทุกออเดอร์และชิ้นใหญ่ที่สุด","skill":"planning","points":10,"hints":["จำนวนชิ้นต่อถาดต้องหารด้วยตัวส่วนของทุกออเดอร์ได้ลงตัว","ตัวส่วนของออเดอร์คือ 6, 4, 12, 2 หาจำนวนที่น้อยที่สุดในตัวเลือกที่ทุกตัวหารลงตัว"],"solution":["ตัวส่วนของออเดอร์: 6, 4, 12, 2","12 เป็นจำนวนชิ้นที่น้อยที่สุดในตัวเลือกที่ทุกตัวส่วนหารลงตัว จึงได้ชิ้นใหญ่ที่สุด"],"options":[{"text":"ตัดถาดละ 2 ชิ้น (ชิ้นละ 1/2 ถาด)","value":2,"ok":false,"why":"2 หารด้วย 6 ไม่ลงตัว จึงแบ่ง 5/6 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 4 ชิ้น (ชิ้นละ 1/4 ถาด)","value":4,"ok":false,"why":"4 หารด้วย 6 ไม่ลงตัว จึงแบ่ง 5/6 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 8 ชิ้น (ชิ้นละ 1/8 ถาด)","value":8,"ok":false,"why":"8 หารด้วย 6 ไม่ลงตัว จึงแบ่ง 5/6 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 12 ชิ้น (ชิ้นละ 1/12 ถาด)","value":12,"ok":true,"why":"แบ่งได้พอดี แต่ชิ้นเล็กเกินจำเป็น 1 ชิ้นแบบ 12 ชิ้นเท่ากับ 1 ชิ้นแบบนี้ ต้องหั่นและหยิบหลายชิ้นขึ้น"},{"text":"ตัดถาดละ 16 ชิ้น (ชิ้นละ 1/16 ถาด)","value":16,"ok":false,"why":"16 หารด้วย 6 ไม่ลงตัว จึงแบ่ง 5/6 ถาดให้พอดีไม่ได้"}],"answer":3,"keepOrder":true,"store":"cut"},{"kind":"choice","prompt":"เหตุผลใดอธิบายได้ถูกต้องว่าแผนนี้จัดได้ครบโดยไม่ขาดไม่เกิน","skill":"planning","points":10,"hints":[],"solution":["ตัดถาดละ 12 ชิ้น: ก้อง 10 + น้ำใส 3 + ใบเฟิร์น 5 + มะปราง 6 = 24 ชิ้น = 2 ถาด","ใบเฟิร์น+มะปราง = 11 ≤ 12 ชิ้น วางถาดเดียวกันได้"],"options":[{"text":"เพราะลูกค้าทุกคนสั่งไม่ถึง 1 ถาด จึงใช้ไม่เกิน 2 ถาดแน่นอน","ok":false,"why":"ลูกค้า 4 คนที่สั่งคนละไม่ถึง 1 ถาด อาจรวมกันเกิน 2 ถาดได้ ต้องหาผลรวมจริง"},{"text":"แปลงเป็นชิ้นละ 1/12 ทุกออเดอร์รวมกันได้ 24 ชิ้น เท่ากับ 2 ถาดพอดี และใบเฟิร์นกับมะปรางใช้ 11 ชิ้น ไม่เกินถาดเดียว","ok":true,"why":""},{"text":"เพราะทุกตัวส่วนหาร 12 ลงตัว","ok":false,"why":"เป็นเพียงเหตุผลว่าตัดชิ้นได้พอดี ยังไม่ได้แสดงว่าปริมาณรวมพอดีและเงื่อนไขถาดเดียวกันทำได้"},{"text":"เพราะตัวเศษรวมกันได้ 12 ซึ่งมากพอ","ok":false,"why":"บวกตัวเศษที่ตัวส่วนต่างกันโดยตรงไม่ได้ ต้องทำตัวส่วนให้เท่ากันก่อน"}],"answer":1},{"kind":"pizza","prompt":"จัดชิ้นพิซซ่าให้ลูกค้าแต่ละคนตรงตามออเดอร์ (มี 2 ถาด)","skill":"final","points":20,"hints":["เลือกชื่อลูกค้าก่อน แล้วแตะชิ้นพิซซ่าเพื่อมอบให้ แตะซ้ำเพื่อยกเลิก","แปลงออเดอร์เป็นจำนวนชิ้น เช่น 5/6 ถาด = 10/12 ถาด คือ 10 ชิ้น"],"solution":["ตัดถาดละ 12 ชิ้น 1 ชิ้น = 1/12 ถาด","ก้อง: 5/6 = 10/12 ถาด จึงได้ 10 ชิ้น","น้ำใส: 1/4 = 3/12 ถาด จึงได้ 3 ชิ้น","ใบเฟิร์น: 5/12 = 5/12 ถาด จึงได้ 5 ชิ้น","มะปราง: 1/2 = 6/12 ถาด จึงได้ 6 ชิ้น","รวม 24 ชิ้น จาก 24 ชิ้นใน 2 ถาด เหลือ 0 ชิ้น","ใบเฟิร์น กับ มะปราง ใช้ 11 ชิ้น ไม่เกิน 12 ชิ้น จึงวางในถาดเดียวกันได้"],"orders":[{"name":"ก้อง","f":{"n":5,"d":6}},{"name":"น้ำใส","f":{"n":1,"d":4}},{"name":"ใบเฟิร์น","f":{"n":5,"d":12}},{"name":"มะปราง","f":{"n":1,"d":2}}],"trays":2,"defaultCut":12,"together":[2,3],"own":null,"minTrays":null}]}', 'challenge', 28),
('math_pizza_chef', 'ออเดอร์มีเงื่อนไข', '{"icon":"📋","story":["มีลูกค้า 5 คน บางคนมีเงื่อนไขพิเศษ ร้านมีพิซซ่า 5 ถาด","วางแผนให้ใช้ถาดน้อยที่สุดโดยทำตามเงื่อนไขทุกข้อ"],"context":[{"type":"table","title":"🧾 ออเดอร์ของลูกค้า","head":["ลูกค้า","สั่ง","เงื่อนไข"],"rows":[["ขิง","1/8 ถาด","ต้องได้จากถาดเดียวกับพลอย"],["ก้อง","1/2 ถาด","-"],["ธาม","1/4 ถาด","ขอถาดแยก ห้ามปนกับคนอื่น"],["นที","7/8 ถาด","-"],["พลอย","3/4 ถาด","ต้องได้จากถาดเดียวกับขิง"]]}],"steps":[{"kind":"fraction","prompt":"ลูกค้าทุกคนสั่งพิซซ่ารวมกันกี่ถาด","skill":"analysis","points":10,"hints":["ตัวส่วนไม่เท่ากัน ต้องหาเศษส่วนที่เท่ากันซึ่งมีตัวส่วนเป็น 8 ก่อน","แปลงทีละออเดอร์ เช่น 1/8 = 1/8 แล้วบวกเฉพาะตัวเศษ"],"solution":["ทำตัวส่วนให้เท่ากันเป็น 8: 1/8 = 1/8, 1/2 = 4/8, 1/4 = 2/8, 7/8 = 7/8, 3/4 = 6/8","บวกตัวเศษ: 1 + 4 + 2 + 7 + 6 = 20 จึงได้ 20/8 = 2 1/2 ถาด"],"answer":{"n":5,"d":2},"unit":"ถาด","mistakes":[{"value":{"n":1,"d":2},"why":"ห้ามบวกตัวส่วนเข้าด้วยกัน ต้องทำตัวส่วนให้เท่ากันก่อน แล้วบวกเฉพาะตัวเศษ"}]},{"kind":"choice","prompt":"เปรียบเทียบแผนการตัด: แผนใดแบ่งได้พอดีทุกออเดอร์และหั่นชิ้นน้อยที่สุด","skill":"planning","points":10,"hints":["จำนวนชิ้นต่อถาดต้องหารด้วยตัวส่วนของทุกออเดอร์ได้ลงตัว","ตัวส่วนของออเดอร์คือ 8, 2, 4 หาจำนวนที่น้อยที่สุดในตัวเลือกที่ทุกตัวหารลงตัว"],"solution":["ตัวส่วนของออเดอร์: 8, 2, 4","8 เป็นจำนวนชิ้นที่น้อยที่สุดในตัวเลือกที่ทุกตัวส่วนหารลงตัว จึงได้ชิ้นใหญ่ที่สุด"],"options":[{"text":"ตัดถาดละ 2 ชิ้น (ชิ้นละ 1/2 ถาด)","value":2,"ok":false,"why":"2 หารด้วย 8 ไม่ลงตัว จึงแบ่ง 1/8 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 4 ชิ้น (ชิ้นละ 1/4 ถาด)","value":4,"ok":false,"why":"4 หารด้วย 8 ไม่ลงตัว จึงแบ่ง 1/8 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 8 ชิ้น (ชิ้นละ 1/8 ถาด)","value":8,"ok":true,"why":"แบ่งได้พอดี แต่ชิ้นเล็กเกินจำเป็น 1 ชิ้นแบบ 8 ชิ้นเท่ากับ 1 ชิ้นแบบนี้ ต้องหั่นและหยิบหลายชิ้นขึ้น"},{"text":"ตัดถาดละ 12 ชิ้น (ชิ้นละ 1/12 ถาด)","value":12,"ok":false,"why":"12 หารด้วย 8 ไม่ลงตัว จึงแบ่ง 1/8 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 16 ชิ้น (ชิ้นละ 1/16 ถาด)","value":16,"ok":false,"why":"แบ่งได้พอดี แต่ชิ้นเล็กเกินจำเป็น 1 ชิ้นแบบ 8 ชิ้นเท่ากับ 2 ชิ้นแบบนี้ ต้องหั่นและหยิบหลายชิ้นขึ้น"}],"answer":2,"keepOrder":true,"store":"cut"},{"kind":"number","prompt":"ภายใต้เงื่อนไขทั้งหมด ต้องใช้พิซซ่าอย่างน้อยกี่ถาด","skill":"planning","points":15,"hints":["ธามใช้ 1 ถาดเต็ม คนอื่นใช้ส่วนที่เหลือไม่ได้","ขิงกับพลอยอยู่ถาดเดียวกัน ที่ว่างในถาดนั้นให้คนอื่นใช้ได้"],"solution":["ตัดถาดละ 8 ชิ้น: ขิง 1, ก้อง 4, ธาม 2, นที 7, พลอย 6 ชิ้น","ธาม ใช้ถาดแยก 1 ถาด","ขิง+พลอย = 7 ชิ้น อยู่ถาดเดียวกัน เหลือที่ว่าง 1 ชิ้น","คนอื่นรวม 11 ชิ้น ใส่ในที่ว่าง 1 ชิ้นก่อน ส่วนที่เกินต้องใช้ถาดใหม่","รวมใช้อย่างน้อย 4 ถาด (ผลรวมทั้งหมด 2 1/2 ถาด แต่เงื่อนไขทำให้ต้องใช้ถาดมากขึ้น)"],"answer":4,"unit":"ถาด","mistakes":[{"value":3,"why":"3 ถาดพอเมื่อไม่มีเงื่อนไข แต่ถาดของธามใช้ร่วมกับคนอื่นไม่ได้"}]},{"kind":"pizza","prompt":"จัดชิ้นพิซซ่าให้ครบทุกออเดอร์ ตามเงื่อนไข โดยใช้ถาดน้อยที่สุด (มีให้ใช้ 5 ถาด)","skill":"final","points":20,"hints":["เลือกชื่อลูกค้าก่อน แล้วแตะชิ้นพิซซ่าเพื่อมอบให้ แตะซ้ำเพื่อยกเลิก","แปลงออเดอร์เป็นจำนวนชิ้น เช่น 1/8 ถาด = 1/8 ถาด คือ 1 ชิ้น"],"solution":["ตัดถาดละ 8 ชิ้น 1 ชิ้น = 1/8 ถาด","ขิง: 1/8 = 1/8 ถาด จึงได้ 1 ชิ้น","ก้อง: 1/2 = 4/8 ถาด จึงได้ 4 ชิ้น","ธาม: 1/4 = 2/8 ถาด จึงได้ 2 ชิ้น","นที: 7/8 = 7/8 ถาด จึงได้ 7 ชิ้น","พลอย: 3/4 = 6/8 ถาด จึงได้ 6 ชิ้น","รวม 20 ชิ้น จาก 32 ชิ้นใน 4 ถาด เหลือ 12 ชิ้น","ขิง กับ พลอย ใช้ 7 ชิ้น ไม่เกิน 8 ชิ้น จึงวางในถาดเดียวกันได้","ธาม ได้ถาดของตัวเอง 1 ถาด ส่วนที่เหลือในถาดนั้นห้ามให้คนอื่น"],"orders":[{"name":"ขิง","f":{"n":1,"d":8}},{"name":"ก้อง","f":{"n":1,"d":2}},{"name":"ธาม","f":{"n":1,"d":4}},{"name":"นที","f":{"n":7,"d":8}},{"name":"พลอย","f":{"n":3,"d":4}}],"trays":5,"defaultCut":8,"together":[0,4],"own":2,"minTrays":4}]}', 'challenge', 29),
('math_pizza_chef', 'ออเดอร์ล้นร้าน!', '{"icon":"🍕","story":["ร้านได้รับออเดอร์ 5 รายการ เชฟมีพิซซ่าอยู่ 2 ถาด","คำนวณก่อนว่าพิซซ่าพอหรือไม่ แล้ววางแผนตัดและจัดชิ้นให้ตรงทุกออเดอร์"],"tip":"","context":[{"type":"table","title":"🧾 ออเดอร์ของลูกค้า","head":["ลูกค้า","สั่ง","เงื่อนไข"],"rows":[["ขิง","5/8 ถาด","-"],["น้ำใส","5/16 ถาด","-"],["นที","1/4 ถาด","-"],["ภูผา","1/2 ถาด","-"],["ก้อง","3/8 ถาด","-"]]}],"steps":[{"kind":"fraction","prompt":"ลูกค้าทุกคนสั่งพิซซ่ารวมกันกี่ถาด","skill":"analysis","points":10,"hints":["ตัวส่วนไม่เท่ากัน ต้องหาเศษส่วนที่เท่ากันซึ่งมีตัวส่วนเป็น 16 ก่อน","แปลงทีละออเดอร์ เช่น 5/8 = 10/16 แล้วบวกเฉพาะตัวเศษ"],"solution":["ทำตัวส่วนให้เท่ากันเป็น 16: 5/8 = 10/16, 5/16 = 5/16, 1/4 = 4/16, 1/2 = 8/16, 3/8 = 6/16","บวกตัวเศษ: 10 + 5 + 4 + 8 + 6 = 33 จึงได้ 33/16 = 2 1/16 ถาด"],"answer":{"n":33,"d":16},"unit":"ถาด","mistakes":[{"value":{"n":15,"d":38},"why":"ห้ามบวกตัวส่วนเข้าด้วยกัน ต้องทำตัวส่วนให้เท่ากันก่อน แล้วบวกเฉพาะตัวเศษ"}]},{"kind":"choice","prompt":"เชฟมีพิซซ่า 2 ถาด เพียงพอสำหรับทุกออเดอร์หรือไม่","skill":"analysis","points":10,"hints":["เขียน 2 ถาดเป็นเศษส่วนที่มีตัวส่วนเดียวกับผลรวม"],"solution":["2 ถาด = 32/16 ส่วนออเดอร์รวม = 33/16"],"options":[{"text":"พอ และยังมีพิซซ่าเหลือ","ok":false,"why":"ยังไม่ใช่ ลองเทียบ: 2 ถาด = 32/16 ส่วนออเดอร์รวม = 33/16"},{"text":"พอดี ไม่เหลือเลย","ok":false,"why":"ยังไม่ใช่ ลองเทียบ: 2 ถาด = 32/16 ส่วนออเดอร์รวม = 33/16"},{"text":"ไม่พอ ต้องอบเพิ่ม","ok":true,"why":"ยังไม่ใช่ ลองเทียบ: 2 ถาด = 32/16 ส่วนออเดอร์รวม = 33/16"}],"answer":2,"keepOrder":true},{"kind":"fraction","prompt":"พิซซ่าขาดอยู่กี่ถาด","skill":"calculation","points":10,"hints":["นำผลรวมออเดอร์ 2 1/16 ลบด้วย 2","2 = 32/16"],"solution":["2 1/16 − 2 = 33/16 − 32/16 = 1/16 ถาด"],"answer":{"n":1,"d":16},"unit":"ถาด"},{"kind":"number","prompt":"เชฟต้องอบพิซซ่าเพิ่มอย่างน้อยกี่ถาด (นับเป็นถาดเต็ม)","skill":"planning","points":10,"hints":["ร้านอบได้ทีละถาดเต็ม ถ้าขาดไม่ถึง 1 ถาดก็ต้องอบ 1 ถาด"],"solution":["ขาด 1/16 ถาด ต้องปัดขึ้นเป็นถาดเต็ม จึงอบเพิ่ม 1 ถาด"],"answer":1,"unit":"ถาด"},{"kind":"choice","prompt":"ควรตัดพิซซ่าถาดละกี่ชิ้น จึงแบ่งได้พอดีทุกออเดอร์และชิ้นใหญ่ที่สุด","skill":"planning","points":10,"hints":["จำนวนชิ้นต่อถาดต้องหารด้วยตัวส่วนของทุกออเดอร์ได้ลงตัว","ตัวส่วนของออเดอร์คือ 8, 16, 4, 2 หาจำนวนที่น้อยที่สุดในตัวเลือกที่ทุกตัวหารลงตัว"],"solution":["ตัวส่วนของออเดอร์: 8, 16, 4, 2","16 เป็นจำนวนชิ้นที่น้อยที่สุดในตัวเลือกที่ทุกตัวส่วนหารลงตัว จึงได้ชิ้นใหญ่ที่สุด"],"options":[{"text":"ตัดถาดละ 2 ชิ้น (ชิ้นละ 1/2 ถาด)","value":2,"ok":false,"why":"2 หารด้วย 8 ไม่ลงตัว จึงแบ่ง 5/8 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 4 ชิ้น (ชิ้นละ 1/4 ถาด)","value":4,"ok":false,"why":"4 หารด้วย 8 ไม่ลงตัว จึงแบ่ง 5/8 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 8 ชิ้น (ชิ้นละ 1/8 ถาด)","value":8,"ok":false,"why":"8 หารด้วย 16 ไม่ลงตัว จึงแบ่ง 5/16 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 12 ชิ้น (ชิ้นละ 1/12 ถาด)","value":12,"ok":false,"why":"12 หารด้วย 8 ไม่ลงตัว จึงแบ่ง 5/8 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 16 ชิ้น (ชิ้นละ 1/16 ถาด)","value":16,"ok":true,"why":"แบ่งได้พอดี แต่ชิ้นเล็กเกินจำเป็น 1 ชิ้นแบบ 16 ชิ้นเท่ากับ 1 ชิ้นแบบนี้ ต้องหั่นและหยิบหลายชิ้นขึ้น"}],"answer":4,"keepOrder":true,"store":"cut"},{"kind":"pizza","prompt":"จัดชิ้นพิซซ่าให้ลูกค้าแต่ละคนตรงตามออเดอร์ (มี 3 ถาด)","skill":"final","points":20,"hints":["เลือกชื่อลูกค้าก่อน แล้วแตะชิ้นพิซซ่าเพื่อมอบให้ แตะซ้ำเพื่อยกเลิก","แปลงออเดอร์เป็นจำนวนชิ้น เช่น 5/8 ถาด = 10/16 ถาด คือ 10 ชิ้น"],"solution":["ตัดถาดละ 16 ชิ้น 1 ชิ้น = 1/16 ถาด","ขิง: 5/8 = 10/16 ถาด จึงได้ 10 ชิ้น","น้ำใส: 5/16 = 5/16 ถาด จึงได้ 5 ชิ้น","นที: 1/4 = 4/16 ถาด จึงได้ 4 ชิ้น","ภูผา: 1/2 = 8/16 ถาด จึงได้ 8 ชิ้น","ก้อง: 3/8 = 6/16 ถาด จึงได้ 6 ชิ้น","รวม 33 ชิ้น จาก 48 ชิ้นใน 3 ถาด เหลือ 15 ชิ้น"],"orders":[{"name":"ขิง","f":{"n":5,"d":8}},{"name":"น้ำใส","f":{"n":5,"d":16}},{"name":"นที","f":{"n":1,"d":4}},{"name":"ภูผา","f":{"n":1,"d":2}},{"name":"ก้อง","f":{"n":3,"d":8}}],"trays":3,"defaultCut":16,"together":null,"own":null,"minTrays":null}]}', 'challenge', 30),
