รด้วย 16 ไม่ลงตัว จึงแบ่ง 15/16 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 8 ชิ้น (ชิ้นละ 1/8 ถาด)","value":8,"ok":false,"why":"8 หารด้วย 16 ไม่ลงตัว จึงแบ่ง 15/16 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 12 ชิ้น (ชิ้นละ 1/12 ถาด)","value":12,"ok":false,"why":"12 หารด้วย 16 ไม่ลงตัว จึงแบ่ง 15/16 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 16 ชิ้น (ชิ้นละ 1/16 ถาด)","value":16,"ok":true,"why":"แบ่งได้พอดี แต่ชิ้นเล็กเกินจำเป็น 1 ชิ้นแบบ 16 ชิ้นเท่ากับ 1 ชิ้นแบบนี้ ต้องหั่นและหยิบหลายชิ้นขึ้น"}],"answer":4,"keepOrder":true,"store":"cut"},{"kind":"choice","prompt":"เหตุผลใดอธิบายได้ถูกต้องว่าแผนนี้จัดได้ครบโดยไม่ขาดไม่เกิน","skill":"planning","points":10,"hints":[],"solution":["ตัดถาดละ 16 ชิ้น: ขิง 15 + มะปราง 3 + ก้อง 2 + น้ำใส 12 = 32 ชิ้น = 2 ถาด","มะปราง+ก้อง = 5 ≤ 16 ชิ้น วางถาดเดียวกันได้"],"options":[{"text":"เพราะตัวเศษรวมกันได้ 22 ซึ่งมากพอ","ok":false,"why":"บวกตัวเศษที่ตัวส่วนต่างกันโดยตรงไม่ได้ ต้องทำตัวส่วนให้เท่ากันก่อน"},{"text":"เพราะลูกค้าทุกคนสั่งไม่ถึง 1 ถาด จึงใช้ไม่เกิน 2 ถาดแน่นอน","ok":false,"why":"ลูกค้า 4 คนที่สั่งคนละไม่ถึง 1 ถาด อาจรวมกันเกิน 2 ถาดได้ ต้องหาผลรวมจริง"},{"text":"แปลงเป็นชิ้นละ 1/16 ทุกออเดอร์รวมกันได้ 32 ชิ้น เท่ากับ 2 ถาดพอดี และมะปรางกับก้องใช้ 5 ชิ้น ไม่เกินถาดเดียว","ok":true,"why":""},{"text":"เพราะทุกตัวส่วนหาร 16 ลงตัว","ok":false,"why":"เป็นเพียงเหตุผลว่าตัดชิ้นได้พอดี ยังไม่ได้แสดงว่าปริมาณรวมพอดีและเงื่อนไขถาดเดียวกันทำได้"}],"answer":2},{"kind":"pizza","prompt":"จัดชิ้นพิซซ่าให้ลูกค้าแต่ละคนตรงตามออเดอร์ (มี 2 ถาด)","skill":"final","points":20,"hints":["เลือกชื่อลูกค้าก่อน แล้วแตะชิ้นพิซซ่าเพื่อมอบให้ แตะซ้ำเพื่อยกเลิก","แปลงออเดอร์เป็นจำนวนชิ้น เช่น 15/16 ถาด = 15/16 ถาด คือ 15 ชิ้น"],"solution":["ตัดถาดละ 16 ชิ้น 1 ชิ้น = 1/16 ถาด","ขิง: 15/16 = 15/16 ถาด จึงได้ 15 ชิ้น","มะปราง: 3/16 = 3/16 ถาด จึงได้ 3 ชิ้น","ก้อง: 1/8 = 2/16 ถาด จึงได้ 2 ชิ้น","น้ำใส: 3/4 = 12/16 ถาด จึงได้ 12 ชิ้น","รวม 32 ชิ้น จาก 32 ชิ้นใน 2 ถาด เหลือ 0 ชิ้น","มะปราง กับ ก้อง ใช้ 5 ชิ้น ไม่เกิน 16 ชิ้น จึงวางในถาดเดียวกันได้"],"orders":[{"name":"ขิง","f":{"n":15,"d":16}},{"name":"มะปราง","f":{"n":3,"d":16}},{"name":"ก้อง","f":{"n":1,"d":8}},{"name":"น้ำใส","f":{"n":3,"d":4}}],"trays":2,"defaultCut":16,"together":[1,2],"own":null,"minTrays":null}]}', 'challenge', 31),
('math_pizza_chef', 'ออเดอร์มีเงื่อนไข', '{"icon":"📋","story":["มีลูกค้า 5 คน บางคนมีเงื่อนไขพิเศษ ร้านมีพิซซ่า 5 ถาด","วางแผนให้ใช้ถาดน้อยที่สุดโดยทำตามเงื่อนไขทุกข้อ"],"context":[{"type":"table","title":"🧾 ออเดอร์ของลูกค้า","head":["ลูกค้า","สั่ง","เงื่อนไข"],"rows":[["ธาม","3/4 ถาด","ต้องได้จากถาดเดียวกับพลอย"],["พลอย","1/6 ถาด","ต้องได้จากถาดเดียวกับธาม"],["นที","1/3 ถาด","-"],["น้ำใส","11/12 ถาด","-"],["ก้อง","1/2 ถาด","ขอถาดแยก ห้ามปนกับคนอื่น"]]}],"steps":[{"kind":"fraction","prompt":"ลูกค้าทุกคนสั่งพิซซ่ารวมกันกี่ถาด","skill":"analysis","points":10,"hints":["ตัวส่วนไม่เท่ากัน ต้องหาเศษส่วนที่เท่ากันซึ่งมีตัวส่วนเป็น 12 ก่อน","แปลงทีละออเดอร์ เช่น 3/4 = 9/12 แล้วบวกเฉพาะตัวเศษ"],"solution":["ทำตัวส่วนให้เท่ากันเป็น 12: 3/4 = 9/12, 1/6 = 2/12, 1/3 = 4/12, 11/12 = 11/12, 1/2 = 6/12","บวกตัวเศษ: 9 + 2 + 4 + 11 + 6 = 32 จึงได้ 32/12 = 2 2/3 ถาด"],"answer":{"n":8,"d":3},"unit":"ถาด","mistakes":[{"value":{"n":17,"d":27},"why":"ห้ามบวกตัวส่วนเข้าด้วยกัน ต้องทำตัวส่วนให้เท่ากันก่อน แล้วบวกเฉพาะตัวเศษ"}]},{"kind":"choice","prompt":"เปรียบเทียบแผนการตัด: แผนใดแบ่งได้พอดีทุกออเดอร์และหั่นชิ้นน้อยที่สุด","skill":"planning","points":10,"hints":["จำนวนชิ้นต่อถาดต้องหารด้วยตัวส่วนของทุกออเดอร์ได้ลงตัว","ตัวส่วนของออเดอร์คือ 4, 6, 3, 12, 2 หาจำนวนที่น้อยที่สุดในตัวเลือกที่ทุกตัวหารลงตัว"],"solution":["ตัวส่วนของออเดอร์: 4, 6, 3, 12, 2","12 เป็นจำนวนชิ้นที่น้อยที่สุดในตัวเลือกที่ทุกตัวส่วนหารลงตัว จึงได้ชิ้นใหญ่ที่สุด"],"options":[{"text":"ตัดถาดละ 2 ชิ้น (ชิ้นละ 1/2 ถาด)","value":2,"ok":false,"why":"2 หารด้วย 4 ไม่ลงตัว จึงแบ่ง 3/4 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 4 ชิ้น (ชิ้นละ 1/4 ถาด)","value":4,"ok":false,"why":"4 หารด้วย 6 ไม่ลงตัว จึงแบ่ง 1/6 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 8 ชิ้น (ชิ้นละ 1/8 ถาด)","value":8,"ok":false,"why":"8 หารด้วย 6 ไม่ลงตัว จึงแบ่ง 1/6 ถาดให้พอดีไม่ได้"},{"text":"ตัดถาดละ 12 ชิ้น (ชิ้นละ 1/12 ถาด)","value":12,"ok":true,"why":"แบ่งได้พอดี แต่ชิ้นเล็กเกินจำเป็น 1 ชิ้นแบบ 12 ชิ้นเท่ากับ 1 ชิ้นแบบนี้ ต้องหั่นและหยิบหลายชิ้นขึ้น"},{"text":"ตัดถาดละ 16 ชิ้น (ชิ้นละ 1/16 ถาด)","value":16,"ok":false,"why":"16 หารด้วย 6 ไม่ลงตัว จึงแบ่ง 1/6 ถาดให้พอดีไม่ได้"}],"answer":3,"keepOrder":true,"store":"cut"},{"kind":"number","prompt":"ภายใต้เงื่อนไขทั้งหมด ต้องใช้พิซซ่าอย่างน้อยกี่ถาด","skill":"planning","points":15,"hints":["ก้องใช้ 1 ถาดเต็ม คนอื่นใช้ส่วนที่เหลือไม่ได้","ธามกับพลอยอยู่ถาดเดียวกัน ที่ว่างในถาดนั้นให้คนอื่นใช้ได้"],"solution":["ตัดถาดละ 12 ชิ้น: ธาม 9, พลอย 2, นที 4, น้ำใส 11, ก้อง 6 ชิ้น","ก้อง ใช้ถาดแยก 1 ถาด","ธาม+พลอย = 11 ชิ้น อยู่ถาดเดียวกัน เหลือที่ว่าง 1 ชิ้น","คนอื่นรวม 15 ชิ้น ใส่ในที่ว่าง 1 ชิ้นก่อน ส่วนที่เกินต้องใช้ถาดใหม่","รวมใช้อย่างน้อย 4 ถาด (ผลรวมทั้งหมด 2 2/3 ถาด แต่เงื่อนไขทำให้ต้องใช้ถาดมากขึ้น)"],"answer":4,"unit":"ถาด","mistakes":[{"value":3,"why":"3 ถาดพอเมื่อไม่มีเงื่อนไข แต่ถาดของก้องใช้ร่วมกับคนอื่นไม่ได้"}]},{"kind":"pizza","prompt":"จัดชิ้นพิซซ่าให้ครบทุกออเดอร์ ตามเงื่อนไข โดยใช้ถาดน้อยที่สุด (มีให้ใช้ 5 ถาด)","skill":"final","points":20,"hints":["เลือกชื่อลูกค้าก่อน แล้วแตะชิ้นพิซซ่าเพื่อมอบให้ แตะซ้ำเพื่อยกเลิก","แปลงออเดอร์เป็นจำนวนชิ้น เช่น 3/4 ถาด = 9/12 ถาด คือ 9 ชิ้น"],"solution":["ตัดถาดละ 12 ชิ้น 1 ชิ้น = 1/12 ถาด","ธาม: 3/4 = 9/12 ถาด จึงได้ 9 ชิ้น","พลอย: 1/6 = 2/12 ถาด จึงได้ 2 ชิ้น","นที: 1/3 = 4/12 ถาด จึงได้ 4 ชิ้น","น้ำใส: 11/12 = 11/12 ถาด จึงได้ 11 ชิ้น","ก้อง: 1/2 = 6/12 ถาด จึงได้ 6 ชิ้น","รวม 32 ชิ้น จาก 48 ชิ้นใน 4 ถาด เหลือ 16 ชิ้น","ธาม กับ พลอย ใช้ 11 ชิ้น ไม่เกิน 12 ชิ้น จึงวางในถาดเดียวกันได้","ก้อง ได้ถาดของตัวเอง 1 ถาด ส่วนที่เหลือในถาดนั้นห้ามให้คนอื่น"],"orders":[{"name":"ธาม","f":{"n":3,"d":4}},{"name":"พลอย","f":{"n":1,"d":6}},{"name":"นที","f":{"n":1,"d":3}},{"name":"น้ำใส","f":{"n":11,"d":12}},{"name":"ก้อง","f":{"n":1,"d":2}}],"trays":5,"defaultCut":12,"together":[0,1],"own":4,"minTrays":4}]}', 'challenge', 32),
('math_chart_builder', 'นักวิเคราะห์ข้อมูลมือโปร', '{"icon":"📊","story":["ข้อมูล: เงินออมสะสมของห้อง ป.5/2 ในแต่ละเดือน","วิเคราะห์ข้อมูล วางแผน สร้างกราฟ แล้วตีความ"],"context":[{"type":"table","title":"📋 ตารางข้อมูล","head":["เดือน","เงินออมสะสม (บาท)"],"rows":[["มิ.ย.","2"],["ก.ค.","7"],["ส.ค.","10"],["ก.ย.","14"]]}],"steps":[{"kind":"choice","prompt":"หมวดใดมีค่ามากที่สุด","skill":"analysis","points":10,"hints":["เทียบค่าทีละแถว จำค่าที่มากที่สุดไว้"],"solution":["ก.ย. = 14 บาท มากที่สุด"],"options":[{"text":"ส.ค.","ok":false,"why":"ส.ค. มี 10 น้อยกว่า ก.ย. ที่มี 14"},{"text":"ก.ค.","ok":false,"why":"ก.ค. มี 7 น้อยกว่า ก.ย. ที่มี 14"},{"text":"ก.ย.","ok":true,"why":"ก.ย. มี 14 น้อยกว่า ก.ย. ที่มี 14"},{"text":"มิ.ย.","ok":false,"why":"มิ.ย. มี 2 น้อยกว่า ก.ย. ที่มี 14"}],"answer":2},{"kind":"number","prompt":"เงินออมสะสมรวมทุกหมวดเท่ากับกี่บาท","skill":"analysis","points":10,"hints":["บวกค่าทุกแถวในตาราง","บวกทีละคู่แล้วตรวจอีกครั้ง"],"solution":["2 + 7 + 10 + 14 = 33 บาท"],"answer":33,"unit":"บาท"},{"kind":"number","prompt":"ค่ามากที่สุดกับค่าน้อยที่สุดต่างกันกี่บาท","skill":"analysis","points":10,"hints":["หาค่ามากที่สุดและน้อยที่สุดก่อน","นำค่ามากที่สุดลบค่าน้อยที่สุด"],"solution":["มากที่สุด ก.ย. = 14, น้อยที่สุด มิ.ย. = 2","14 − 2 = 12 บาท"],"answer":12,"unit":"บาท"},{"kind":"plan","prompt":"วางแผนกราฟ: เลือกให้ครบทุกหัวข้อ","skill":"planning","points":15,"hints":["ข้อมูลที่วัดซ้ำตามเวลา เหมาะกับกราฟเส้น","ค่ามากที่สุดคือ 14 หาร 14 ด้วยแต่ละสเกล แล้วเลือกสเกลที่ละเอียดที่สุดที่ใช้ไม่เกิน 10 ช่อง"],"solution":["ชนิดกราฟ: กราฟเส้น เพราะข้อมูลเปลี่ยนตามเวลา","แกน X: เดือน · แกน Y: เงินออมสะสม (บาท)","สเกล: 14 ÷ 2 ≈ 7 ช่อง ไม่เกิน 10 ช่อง แต่ 1 ต้องใช้ 14 ช่อง"],"fields":[{"id":"type","label":"ชนิดกราฟ","store":"chartType","options":[{"text":"แผนภูมิแท่ง","value":"bar","ok":false,"why":"ข้อมูลนี้เปลี่ยนแปลงตามเวลา กราฟเส้นแสดงการขึ้นลงต่อเนื่องได้ชัดกว่า"},{"text":"กราฟเส้น","value":"line","ok":true,"why":""},{"text":"แผนภูมิรูปวงกลม","value":"pie","ok":false,"