่าละเอียดได้ยาก สเกลที่ละเอียดกว่าและยังพอดีพื้นที่คือ 25"},{"text":"ช่องละ 50 กระป๋อง (ใช้ 4 ช่อง)","value":50,"ok":false,"why":"ใช้ได้ แต่แท่งจะเตี้ยและอ่านค่าละเอียดได้ยาก สเกลที่ละเอียดกว่าและยังพอดีพื้นที่คือ 25"},{"text":"ช่องละ 100 กระป๋อง (ใช้ 2 ช่อง)","value":100,"ok":false,"why":"ใช้ได้ แต่แท่งจะเตี้ยและอ่านค่าละเอียดได้ยาก สเกลที่ละเอียดกว่าและยังพอดีพื้นที่คือ 25"}],"answer":1}]},{"kind":"chart","prompt":"สร้างกราฟ: วางหมวดหมู่บนแกน X ตามลำดับในตาราง แล้วปรับความสูงทุกแท่งให้ตรงข้อมูล","skill":"final","points":20,"hints":["แตะชื่อหมวดหมู่ด้านล่างเพื่อวางบนแกน X ตามลำดับ แตะป้ายใต้แท่งเพื่อเอาออก","แตะหรือลากในคอลัมน์เพื่อกำหนดความสูง แล้วใช้ปุ่ม − / + ปรับละเอียด"],"solution":["ลำดับแกน X: ป.4/1 → ป.4/2 → ป.5/1 → ป.5/2 → ป.6/1 → ป.6/2 → ป.6/3","ป.4/1 = 10 กระป๋อง","ป.4/2 = 150 กระป๋อง","ป.5/1 = 60 กระป๋อง","ป.5/2 = 200 กระป๋อง","ป.6/1 = 20 กระป๋อง","ป.6/2 = 40 กระป๋อง","ป.6/3 = 140 กระป๋อง"],"labels":["ป.4/1","ป.4/2","ป.5/1","ป.5/2","ป.6/1","ป.6/2","ป.6/3"],"values":[10,150,60,200,20,40,140],"order":["ป.4/1","ป.4/2","ป.5/1","ป.5/2","ป.6/1","ป.6/2","ป.6/3"],"orderRule":"table","unit":"กระป๋อง","fine":10,"defaultScale":25,"defaultType":"bar","grid":8},{"kind":"choice","prompt":"ข้อสรุปใดถูกต้องตามกราฟ","skill":"interpretation","points":10,"hints":["ตรวจข้อสรุปทีละข้อกับค่าในกราฟ"],"solution":["แท่งสูงสุดคือ ป.5/2 = 200 กระป๋อง"],"options":[{"text":"ป.4/2 มากกว่า ป.5/1 อยู่ 100 กระป๋อง","ok":false,"why":"150 − 60 = 90 ไม่ใช่ 100"},{"text":"ป.4/1 มีค่ามากที่สุด","ok":false,"why":"ป.4/1 มีค่าน้อยที่สุด (10 กระป๋อง)"},{"text":"ป.5/1 มากกว่า ป.4/2","ok":false,"why":"ป.5/1 มี 60 น้อยกว่า ป.4/2 ที่มี 150"},{"text":"ป.5/2 มีค่ามากที่สุด คือ 200 กระป๋อง","ok":true,"why":""}],"answer":3}]}', 'challenge', 25),
