('math_fraction_quest', 'ห่อของขวัญวันเกิด', '{"icon":"🎀","story":["มีริบบิ้นยาว 2 เมตร ราคาเมตรละ 18 บาท","ผูกกล่องของขวัญ 2 ใบ ใช้ 1/8 เมตร, 1/4 เมตร"],"context":[],"steps":[{"kind":"choice","prompt":"ข้อมูลใดไม่จำเป็นต่อการหาความยาวริบบิ้นที่เหลือ","skill":"analysis","points":5,"hints":[],"solution":["คำถามถามความยาว ไม่เกี่ยวกับราคา"],"options":[{"text":"ความยาวริบบิ้นที่มี 2 เมตร","ok":false,"why":"ต้องใช้ความยาวที่มีเป็นตัวตั้ง"},{"text":"ราคาริบบิ้นเมตรละ 18 บาท","ok":true,"why":""},{"text":"ความยาวที่ใช้ผูกกล่องแต่ละใบ","ok":false,"why":"ต้องใช้หาความยาวที่ใช้ไปทั้งหมด"}],"answer":1},{"kind":"fraction","prompt":"ใช้ริบบิ้นไปทั้งหมดกี่เมตร","skill":"calculation","points":10,"hints":["ทำตัวส่วนให้เท่ากันเป็น 8","1/8 + 2/8"],"solution":["ทำตัวส่วนให้เท่ากันเป็น 8: 1/8 = 1/8, 1/4 = 2/8","บวกตัวเศษ: 1 + 2 = 3 จึงได้ 3/8 = 3/8 เมตร"],"answer":{"n":3,"d":8},"unit":"เมตร","mistakes":[{"value":{"n":1,"d":6},"why":"บวกตัวส่วนเข้าด้วยกันไม่ได้ ต้องทำตัวส่วนให้เท่ากันก่อน"}]},{"kind":"fraction","prompt":"เหลือริบบิ้นกี่เมตร","skill":"final","points":10,"hints":["2 − 3/8","2 = 16/8"],"solution":["2 − 3/8 = 16/8 − 3/8 = 1 5/8 เมตร"],"answer":{"n":13,"d":8},"unit":"เมตร"}]}', 'easy', 1),
('math_fraction_quest', 'ถังน้ำรดผัก', '{"icon":"🪣","story":["ถังน้ำมีน้ำ 5/8 ถัง ใช้รดผักไป 1/2 ถัง แล้วเติมน้ำฝนลงไปอีก 3/8 ถัง","แปลงผักมี 6 แปลง และถังใบนี้สูง 60 เซนติเมตร"],"context":[],"steps":[{"kind":"fraction","prompt":"หลังใช้น้ำ เหลือน้ำในถังกี่ถัง","skill":"calculation","points":10,"hints":["5/8 − 1/2"],"solution":["ค.ร.น. ของ 8 และ 2 คือ 8","5/8 − 1/2 = 5/8 − 4/8 = 1/8"],"answer":{"n":1,"d":8},"unit":"ถัง"},{"kind":"fraction","prompt":"ถ้าถังใหญ่พอ หลังเติมน้ำจะมีน้ำรวมกี่ถัง","skill":"calculation","points":10,"hints":["นำคำตอบขั้นก่อนบวกน้ำที่เติม"],"solution":["ค.ร.น. ของ 8 และ 8 คือ 8","1/8 + 3/8 = 1/8 + 3/8 = 1/2"],"answer":{"n":1,"d":2},"unit":"ถัง"},{"kind":"choice","prompt":"น้ำในถังเป็นอย่างไร","skill":"analysis","points":10,"hints":[],"solution":["1/2 น้อยกว่า 1"],"options":[{"text":"ยังไม่เต็มถัง","ok":true,"why":"1/2 เทียบกับ 1 ถัง"},{"text":"เต็มถังพอดี","ok":false,"why":"1/2 เทียบกับ 1 ถัง"},{"text":"ล้นถัง","ok":false,"why":"1/2 เทียบกับ 1 ถัง"}],"answer":0,"keepOrder":true},{"kind":"fraction","prompt":"ต้องเติมน้ำอีกกี่ถังจึงจะเต็มพอดี","skill":"final","points":10,"hints":["1 − 1/2"],"solution":["1 − 1/2 = 1/2 ถัง"],"answer":{"n":1,"d":2},"unit":"ถัง"}]}', 'easy', 2),
('math_fraction_quest', 'สองสูตรขนมปัง', '{"icon":"🥖","story":["สูตร A ใช้แป้งสาลี 1/4 ถ้วย และแป้งข้าว 1/2 ถ้วย","สูตร B ใช้แป้งสาลี 1 ถ้วย และแป้งข้าว 3/4 ถ้วย","ทั้งสองสูตรอบที่ 180 องศาเซลเซียส นาน 25 นาที"],"context":[],"steps":[{"kind":"fraction","prompt":"สูตร A ใช้แป้งรวมกี่ถ้วย","skill":"calculation","points":10,"hints":["หา ค.ร.น. ของ 4 และ 2"],"solution":["ค.ร.น. ของ 4 และ 2 คือ 4","1/4 + 1/2 = 1/4 + 2/4 = 3/4"],"answer":{"n":3,"d":4},"unit":"ถ้วย"},{"kind":"fraction","prompt":"สูตร B ใช้แป้งรวมกี่ถ้วย","skill":"calculation","points":10,"hints":["1 = 4/4"],"solution":["1 + 3/4 = 1 3/4 ถ้วย"],"answer":{"n":7,"d":4},"unit":"ถ้วย"},{"kind":"choice","prompt":"สูตรใดใช้แป้งน้อยกว่า","skill":"analysis","points":10,"hints":[],"solution":["3/4 < 1 3/4"],"options":[{"text":"สูตร A","ok":true,"why":"3/4 กับ 1 3/4 ทำตัวส่วนให้เท่ากันแล้วเทียบ"},{"text":"สูตร B","ok":false,"why":"3/4 กับ 1 3/4 ทำตัวส่วนให้เท่ากันแล้วเทียบ"}],"answer":0,"keepOrder":true},{"kind":"fraction","prompt":"สูตรที่ใช้แป้งน้อยกว่า ประหยัดแป้งได้กี่ถ้วย","skill":"final","points":10,"hints":["นำปริมาณที่มากกว่าลบปริมาณที่น้อยกว่า"],"solution":["ค.ร.น. ของ 4 และ 4 คือ 4","1 3/4 − 3/4 = 7/4 − 3/4 = 1"],"answer":{"n":1,"d":1},"unit":"ถ้วย"}]}', 'easy', 3),
