('math_fraction_quest', 'ตรวจการบ้านเพื่อน', '{"icon":"📝","story":["แพรวคิดว่า 5/8 + 1/4 = 6/12 โดยบวกตัวเศษกับตัวเศษ และตัวส่วนกับตัวส่วน"],"context":[],"steps":[{"kind":"choice","prompt":"วิธีของแพรวถูกหรือไม่","skill":"planning","points":10,"hints":[],"solution":["เศษส่วนบวกกันได้เมื่อแบ่งเป็นส่วนขนาดเท่ากัน จึงต้องทำตัวส่วนให้เท่ากันก่อน"],"options":[{"text":"ถูก เพราะบวกทั้งตัวเศษและตัวส่วนครบแล้ว","ok":false,"why":"ลองเช็ก: 1/2 + 1/2 ต้องได้ 1 แต่วิธีนี้ได้ 2/4 = 1/2"},{"text":"ถูก ถ้าตัดทอนเป็นเศษส่วนอย่างต่ำก่อน","ok":false,"why":"การตัดทอนไม่ช่วย เพราะการบวกตัวส่วนผิดตั้งแต่ต้น"},{"text":"ผิด เพราะต้องทำตัวส่วนให้เท่ากันก่อน แล้วบวกเฉพาะตัวเศษ","ok":true,"why":""}],"answer":2},{"kind":"fraction","prompt":"คำตอบที่ถูกต้องของ 5/8 + 1/4 คือเท่าไร","skill":"calculation","points":10,"hints":["หา ค.ร.น. ของ 8 และ 4","5/8 + 2/8"],"solution":["ค.ร.น. ของ 8 และ 4 คือ 8","5/8 + 1/4 = 5/8 + 2/8 = 7/8"],"answer":{"n":7,"d":8},"mistakes":[{"value":{"n":1,"d":2},"why":"นี่คือคำตอบที่ผิดแบบเดียวกับเพื่อน"}]},{"kind":"choice","prompt":"ตรวจด้วยการประมาณ: ผลบวกที่ถูกต้องต้องมากกว่า 5/8 หรือไม่","skill":"analysis","points":5,"hints":[],"solution":["6/12 ไม่มากกว่า 5/8 จึงเป็นไปไม่ได้"],"options":[{"text":"ต้องมากกว่า เพราะบวกจำนวนที่มากกว่า 0 เข้าไป และคำตอบของแพรวไม่มากกว่า จึงผิดแน่นอน","ok":true,"why":""},{"text":"ไม่จำเป็นต้องมากกว่า","ok":false,"why":"การบวกจำนวนบวกเพิ่มเข้าไป ผลลัพธ์ต้องมากกว่าตัวตั้งเสมอ"}],"answer":0,"keepOrder":true},{"kind":"fraction","prompt":"คำตอบของแพรวน้อยกว่าคำตอบที่ถูกอยู่เท่าไร","skill":"final","points":10,"hints":["7/8 − 1/2"],"solution":["ค.ร.น. ของ 8 และ 2 คือ 8","7/8 − 1/2 = 7/8 − 4/8 = 3/8"],"answer":{"n":3,"d":8}}]}', 'medium', 10),
('math_fraction_quest', 'ถังน้ำรดผัก', '{"icon":"🪣","story":["ถังน้ำมีน้ำ 2/3 ถัง ใช้รดผักไป 3/8 ถัง แล้วเติมน้ำฝนลงไปอีก 3/4 ถัง","แปลงผักมี 6 แปลง และถังใบนี้สูง 60 เซนติเมตร"],"context":[],"steps":[{"kind":"fraction","prompt":"หลังใช้น้ำ เหลือน้ำในถังกี่ถัง","skill":"calculation","points":10,"hints":["2/3 − 3/8"],"solution":["ค.ร.น. ของ 3 และ 8 คือ 24","2/3 − 3/8 = 16/24 − 9/24 = 7/24"],"answer":{"n":7,"d":24},"unit":"ถัง"},{"kind":"fraction","prompt":"ถ้าถังใหญ่พอ หลังเติมน้ำจะมีน้ำรวมกี่ถัง","skill":"calculation","points":10,"hints":["นำคำตอบขั้นก่อนบวกน้ำที่เติม"],"solution":["ค.ร.น. ของ 24 และ 4 คือ 24","7/24 + 3/4 = 7/24 + 18/24 = 1 1/24"],"answer":{"n":25,"d":24},"unit":"ถัง"},{"kind":"choice","prompt":"น้ำในถังเป็นอย่างไร","skill":"analysis","points":10,"hints":[],"solution":["1 1/24 มากกว่า 1"],"options":[{"text":"ยังไม่เต็มถัง","ok":false,"why":"1 1/24 เทียบกับ 1 ถัง"},{"text":"เต็มถังพอดี","ok":false,"why":"1 1/24 เทียบกับ 1 ถัง"},{"text":"ล้นถัง","ok":true,"why":"1 1/24 เทียบกับ 1 ถัง"}],"answer":2,"keepOrder":true},{"kind":"fraction","prompt":"น้ำล้นออกมากี่ถัง","skill":"final","points":10,"hints":["1 1/24 − 1"],"solution":["1 1/24 − 1 = 1/24 ถัง"],"answer":{"n":1,"d":24},"unit":"ถัง"}]}', 'medium', 11),
('math_fraction_quest', 'สองสูตรขนมปัง', '{"icon":"🥖","story":["สูตร A ใช้แป้งสาลี 1/8 ถ้วย และแป้งข้าว 1/2 ถ้วย","สูตร B ใช้แป้งสาลี 1 ถ้วย และแป้งข้าว 3/5 ถ้วย","ทั้งสองสูตรอบที่ 180 องศาเซลเซียส นาน 25 นาที"],"context":[],"steps":[{"kind":"fraction","prompt":"สูตร A ใช้แป้งรวมกี่ถ้วย","skill":"calculation","points":10,"hints":["หา ค.ร.น. ของ 8 และ 2"],"solution":["ค.ร.น. ของ 8 และ 2 คือ 8","1/8 + 1/2 = 1/8 + 4/8 = 5/8"],"answer":{"n":5,"d":8},"unit":"ถ้วย"},{"kind":"fraction","prompt":"สูตร B ใช้แป้งรวมกี่ถ้วย","skill":"calculation","points":10,"hints":["1 = 5/5"],"solution":["1 + 3/5 = 1 3/5 ถ้วย"],"answer":{"n":8,"d":5},"unit":"ถ้วย"},{"kind":"choice","prompt":"สูตรใดใช้แป้งน้อยกว่า","skill":"analysis","points":10,"hints":[],"solution":["5/8 < 1 3/5"],"options":[{"text":"สูตร A","ok":true,"why":"5/8 กับ 1 3/5 ทำตัวส่วนให้เท่ากันแล้วเทียบ"},{"text":"สูตร B","ok":false,"why":"5/8 กับ 1 3/5 ทำตัวส่วนให้เท่ากันแล้วเทียบ"}],"answer":0,"keepOrder":true},{"kind":"fraction","prompt":"สูตรที่ใช้แป้งน้อยกว่า ประหยัดแป้งได้กี่ถ้วย","skill":"final","points":10,"hints":["นำปริมาณที่มากกว่าลบปริมาณที่น้อยกว่า"],"solution":["ค.ร.น. ของ 5 และ 8 คือ 40","1 3/5 − 5/8 = 64/40 − 25/40 = 39/40"],"answer":{"n":39,"d":40},"unit":"ถ้วย"}]}', 'medium', 12),
('math_fraction_quest', 'ห่อของขวัญวันเกิด', '{"icon":"🎀","story":["มีริบบิ้นยาว 3 เมตร ราคาเมตรละ 16 บาท","ผูกกล่องของขวัญ 2 ใบ ใช้ 4/5 เมตร, 5/8 เมตร"],"context":[],"steps":[{"kind":"choice","prompt":"ข้อมูลใดไม่จำเป็นต่อการหาความยาวริบบิ้นที่เหลือ","skill":"analysis","points":5,"hints":[],"solution":["คำถามถามความยาว ไม่เกี่ยวกับราคา"],"options":[{"text":"ราคาริบบิ้นเมตรละ 16 บาท","ok":true,"why":""},{"text":"ความยาวริบบิ้นที่มี 3 เมตร","ok":false,"why":"ต้องใช้ความยาวที่มีเป็นตัวตั้ง"},{"text":"ความยาวที่ใช้ผูกกล่องแต่ละใบ","ok":false,"why":"ต้องใช้หาความยาวที่ใช้ไปทั้งหมด"}],"answer":0},{"kind":"fraction","prompt":"ใช้ริบบิ้นไปทั้งหมดกี่เมตร","skill":"calculation","points":10,"hints":["ทำตัวส่วนให้เท่ากันเป็น 40","32/40 + 25/40"],"solution":["ทำตัวส่วนให้เท่ากันเป็น 40: 4/5 = 32/40, 5/8 = 25/40","บวกตัวเศษ: 32 + 25 = 57 จึงได้ 57/40 = 1 17/40 เมตร"],"answer":{"n":57,"d":40},"unit":"เมตร","mistakes":[{"value":{"n":9,"d":13},"why":"บวกตัวส่วนเข้าด้วยกันไม่ได้ ต้องทำตัวส่วนให้เท่ากันก่อน"}]},{"kind":"fraction","prompt":"เหลือริบบิ้นกี่เมตร","skill":"final","points":10,"hints":["3 − 1 17/40","3 = 120/40"],"solution":["3 − 1 17/40 = 120/40 − 57/40 = 1 23/40 เมตร"],"answer":{"n":63,"d":40},"unit":"เมตร"}]}', 'medium', 13),
