('math_fraction_quest', 'ร้านเค้กวันเด็ก', '{"icon":"🎂","story":["เค้ก 1 ก้อนใช้น้ำตาล 3/8 กิโลกรัม ต้องทำ 3 ก้อน","ร้านมีน้ำตาล 4 กิโลกรัม และมีไข่ 30 ฟอง"],"context":[],"steps":[{"kind":"fraction","prompt":"ทำเค้ก 3 ก้อน ต้องใช้น้ำตาลกี่กิโลกรัม","skill":"calculation","points":10,"hints":["คูณเศษส่วนกับจำนวนนับ: คูณเฉพาะตัวเศษ"],"solution":["3/8 × 3 = 9/8 = 1 1/8 กิโลกรัม"],"answer":{"n":9,"d":8},"unit":"กิโลกรัม"},{"kind":"fraction","prompt":"น้ำตาลเหลือกี่กิโลกรัม","skill":"calculation","points":10,"hints":["นำปริมาณที่มากกว่าลบปริมาณที่น้อยกว่า"],"solution":["ค.ร.น. ของ 1 และ 8 คือ 8","4 − 1 1/8 = 32/8 − 9/8 = 2 7/8"],"answer":{"n":23,"d":8},"unit":"กิโลกรัม"},{"kind":"number","prompt":"ด้วยน้ำตาลที่มี ทำเค้กได้มากที่สุดกี่ก้อน","skill":"planning","points":10,"hints":["หาว่า 4 มี 3/8 อยู่กี่ส่วนเต็ม","4 = 32/8 แล้วหารด้วย 3"],"solution":["4 = 32/8 กิโลกรัม","32 ÷ 3 = 10 2/3 ทำได้เต็มก้อน 10 ก้อน"],"answer":10,"unit":"ก้อน"}]}', 'hard', 20),
