('math_fraction_quest', 'ถังน้ำรดผัก', '{"icon":"🪣","story":["ถังน้ำมีน้ำ 7/9 ถัง ใช้รดผักไป 7/12 ถัง แล้วเติมน้ำฝนลงไปอีก 1/6 ถัง","แปลงผักมี 6 แปลง และถังใบนี้สูง 60 เซนติเมตร"],"context":[],"steps":[{"kind":"fraction","prompt":"หลังใช้น้ำ เหลือน้ำในถังกี่ถัง","skill":"calculation","points":10,"hints":["7/9 − 7/12"],"solution":["ค.ร.น. ของ 9 และ 12 คือ 36","7/9 − 7/12 = 28/36 − 21/36 = 7/36"],"answer":{"n":7,"d":36},"unit":"ถัง"},{"kind":"fraction","prompt":"ถ้าถังใหญ่พอ หลังเติมน้ำจะมีน้ำรวมกี่ถัง","skill":"calculation","points":10,"hints":["นำคำตอบขั้นก่อนบวกน้ำที่เติม"],"solution":["ค.ร.น. ของ 36 และ 6 คือ 36","7/36 + 1/6 = 7/36 + 6/36 = 13/36"],"answer":{"n":13,"d":36},"unit":"ถัง"},{"kind":"choice","prompt":"น้ำในถังเป็นอย่างไร","skill":"analysis","points":10,"hints":[],"solution":["13/36 น้อยกว่า 1"],"options":[{"text":"ยังไม่เต็มถัง","ok":true,"why":"13/36 เทียบกับ 1 ถัง"},{"text":"เต็มถังพอดี","ok":false,"why":"13/36 เทียบกับ 1 ถัง"},{"text":"ล้นถัง","ok":false,"why":"13/36 เทียบกับ 1 ถัง"}],"answer":0,"keepOrder":true},{"kind":"fraction","prompt":"ต้องเติมน้ำอีกกี่ถังจึงจะเต็มพอดี","skill":"final","points":10,"hints":["1 − 13/36"],"solution":["1 − 13/36 = 23/36 ถัง"],"answer":{"n":23,"d":36},"unit":"ถัง"}]}', 'hard', 23),
