('math_fraction_quest', 'ร้านเค้กวันเด็ก', '{"icon":"🎂","story":["เค้ก 1 ก้อนใช้น้ำตาล 5/12 กิโลกรัม ต้องทำ 7 ก้อน","ร้านมีน้ำตาล 4 กิโลกรัม และมีไข่ 30 ฟอง"],"context":[],"steps":[{"kind":"fraction","prompt":"ทำเค้ก 7 ก้อน ต้องใช้น้ำตาลกี่กิโลกรัม","skill":"calculation","points":10,"hints":["คูณเศษส่วนกับจำนวนนับ: คูณเฉพาะตัวเศษ"],"solution":["5/12 × 7 = 35/12 = 2 11/12 กิโลกรัม"],"answer":{"n":35,"d":12},"unit":"กิโลกรัม"},{"kind":"fraction","prompt":"น้ำตาลเหลือกี่กิโลกรัม","skill":"calculation","points":10,"hints":["นำปริมาณที่มากกว่าลบปริมาณที่น้อยกว่า"],"solution":["ค.ร.น. ของ 1 และ 12 คือ 12","4 − 2 11/12 = 48/12 − 35/12 = 1 1/12"],"answer":{"n":13,"d":12},"unit":"กิโลกรัม"},{"kind":"number","prompt":"ด้วยน้ำตาลที่มี ทำเค้กได้มากที่สุดกี่ก้อน","skill":"planning","points":10,"hints":["หาว่า 4 มี 5/12 อยู่กี่ส่วนเต็ม","4 = 48/12 แล้วหารด้วย 5"],"solution":["4 = 48/12 กิโลกรัม","48 ÷ 5 = 9 3/5 ทำได้เต็มก้อน 9 ก้อน"],"answer":9,"unit":"ก้อน"}]}', 'challenge', 25),
('math_fraction_quest', 'ห่อของขวัญวันเกิด', '{"icon":"🎀","story":["มีริบบิ้นยาว 3 เมตร ราคาเมตรละ 12 บาท","ผูกกล่องของขวัญ 3 ใบ ใช้ 3/5 เมตร, 5/6 เมตร, 1/8 เมตร"],"context":[],"steps":[{"kind":"choice","prompt":"ข้อมูลใดไม่จำเป็นต่อการหาความยาวริบบิ้นที่เหลือ","skill":"analysis","points":5,"hints":[],"solution":["คำถามถามความยาว ไม่เกี่ยวกับราคา"],"options":[{"text":"ความยาวริบบิ้นที่มี 3 เมตร","ok":false,"why":"ต้องใช้ความยาวที่มีเป็นตัวตั้ง"},{"text":"ความยาวที่ใช้ผูกกล่องแต่ละใบ","ok":false,"why":"ต้องใช้หาความยาวที่ใช้ไปทั้งหมด"},{"text":"ราคาริบบิ้นเมตรละ 12 บาท","ok":true,"why":""}],"answer":2},{"kind":"fraction","prompt":"ใช้ริบบิ้นไปทั้งหมดกี่เมตร","skill":"calculation","points":10,"hints":["ทำตัวส่วนให้เท่ากันเป็น 120","72/120 + 100/120 + 15/120"],"solution":["ทำตัวส่วนให้เท่ากันเป็น 120: 3/5 = 72/120, 5/6 = 100/120, 1/8 = 15/120","บวกตัวเศษ: 72 + 100 + 15 = 187 จึงได้ 187/120 = 1 67/120 เมตร"],"answer":{"n":187,"d":120},"unit":"เมตร","mistakes":[{"value":{"n":9,"d":19},"why":"บวกตัวส่วนเข้าด้วยกันไม่ได้ ต้องทำตัวส่วนให้เท่ากันก่อน"}]},{"kind":"fraction","prompt":"เหลือริบบิ้นกี่เมตร","skill":"final","points":10,"hints":["3 − 1 67/120","3 = 360/120"],"solution":["3 − 1 67/120 = 360/120 − 187/120 = 1 53/120 เมตร"],"answer":{"n":173,"d":120},"unit":"เมตร"},{"kind":"choice","prompt":"ต้องเก็บริบบิ้นอย่างน้อย 1/2 เมตรไว้ผูกโบว์ใหญ่ ริบบิ้นที่เหลือพอหรือไม่","skill":"final","points":10,"hints":[],"solution":["เทียบ 1 53/120 กับ 1/2 โดยทำตัวส่วนเป็น 120"],"options":[{"text":"พอ","ok":true,"why":"1 53/120 = 173/120 น้อยกว่า 1/2 = 60/120"},{"text":"ไม่พอ","ok":false,"why":"1 53/120 = 173/120 ไม่น้อยกว่า 1/2 = 60/120"}],"answer":0,"keepOrder":true}]}', 'challenge', 26),
('math_fraction_quest', 'ตรวจการบ้านเพื่อน', '{"icon":"📝","story":["ใบเฟิร์นคิดว่า 7/9 + 3/7 = 10/16 โดยบวกตัวเศษกับตัวเศษ และตัวส่วนกับตัวส่วน"],"context":[],"steps":[{"kind":"choice","prompt":"วิธีของใบเฟิร์นถูกหรือไม่","skill":"planning","points":10,"hints":[],"solution":["เศษส่วนบวกกันได้เมื่อแบ่งเป็นส่วนขนาดเท่ากัน จึงต้องทำตัวส่วนให้เท่ากันก่อน"],"options":[{"text":"ถูก ถ้าตัดทอนเป็นเศษส่วนอย่างต่ำก่อน","ok":false,"why":"การตัดทอนไม่ช่วย เพราะการบวกตัวส่วนผิดตั้งแต่ต้น"},{"text":"ผิด เพราะต้องทำตัวส่วนให้เท่ากันก่อน แล้วบวกเฉพาะตัวเศษ","ok":true,"why":""},{"text":"ถูก เพราะบวกทั้งตัวเศษและตัวส่วนครบแล้ว","ok":false,"why":"ลองเช็ก: 1/2 + 1/2 ต้องได้ 1 แต่วิธีนี้ได้ 2/4 = 1/2"}],"answer":1},{"kind":"fraction","prompt":"คำตอบที่ถูกต้องของ 7/9 + 3/7 คือเท่าไร","skill":"calculation","points":10,"hints":["หา ค.ร.น. ของ 9 และ 7","49/63 + 27/63"],"solution":["ค.ร.น. ของ 9 และ 7 คือ 63","7/9 + 3/7 = 49/63 + 27/63 = 1 13/63"],"answer":{"n":76,"d":63},"mistakes":[{"value":{"n":5,"d":8},"why":"นี่คือคำตอบที่ผิดแบบเดียวกับเพื่อน"}]},{"kind":"choice","prompt":"ตรวจด้วยการประมาณ: ผลบวกที่ถูกต้องต้องมากกว่า 7/9 หรือไม่","skill":"analysis","points":5,"hints":[],"solution":["10/16 ไม่มากกว่า 7/9 จึงเป็นไปไม่ได้"],"options":[{"text":"ต้องมากกว่า เพราะบวกจำนวนที่มากกว่า 0 เข้าไป และคำตอบของใบเฟิร์นไม่มากกว่า จึงผิดแน่นอน","ok":true,"why":""},{"text":"ไม่จำเป็นต้องมากกว่า","ok":false,"why":"การบวกจำนวนบวกเพิ่มเข้าไป ผลลัพธ์ต้องมากกว่าตัวตั้งเสมอ"}],"answer":0,"keepOrder":true},{"kind":"fraction","prompt":"คำตอบของใบเฟิร์นน้อยกว่าคำตอบที่ถูกอยู่เท่าไร","skill":"final","points":10,"hints":["1 13/63 − 5/8"],"solution":["ค.ร.น. ของ 63 และ 8 คือ 504","1 13/63 − 5/8 = 608/504 − 315/504 = 293/504"],"answer":{"n":293,"d":504}}]}', 'challenge', 27),
