('math_fraction_quest', 'ร้านเค้กวันเด็ก', '{"icon":"🎂","story":["เค้ก 1 ก้อนใช้น้ำตาล 3/5 กิโลกรัม ต้องทำ 6 ก้อน","ร้านมีน้ำตาล 4 กิโลกรัม และมีไข่ 30 ฟอง"],"context":[],"steps":[{"kind":"fraction","prompt":"ทำเค้ก 6 ก้อน ต้องใช้น้ำตาลกี่กิโลกรัม","skill":"calculation","points":10,"hints":["คูณเศษส่วนกับจำนวนนับ: คูณเฉพาะตัวเศษ"],"solution":["3/5 × 6 = 18/5 = 3 3/5 กิโลกรัม"],"answer":{"n":18,"d":5},"unit":"กิโลกรัม"},{"kind":"fraction","prompt":"น้ำตาลเหลือกี่กิโลกรัม","skill":"calculation","points":10,"hints":["นำปริมาณที่มากกว่าลบปริมาณที่น้อยกว่า"],"solution":["ค.ร.น. ของ 1 และ 5 คือ 5","4 − 3 3/5 = 20/5 − 18/5 = 2/5"],"answer":{"n":2,"d":5},"unit":"กิโลกรัม"},{"kind":"number","prompt":"ด้วยน้ำตาลที่มี ทำเค้กได้มากที่สุดกี่ก้อน","skill":"planning","points":10,"hints":["หาว่า 4 มี 3/5 อยู่กี่ส่วนเต็ม","4 = 20/5 แล้วหารด้วย 3"],"solution":["4 = 20/5 กิโลกรัม","20 ÷ 3 = 6 2/3 ทำได้เต็มก้อน 6 ก้อน"],"answer":6,"unit":"ก้อน"}]}', 'challenge', 29),
('math_fraction_quest', 'ห่อของขวัญวันเกิด', '{"icon":"🎀","story":["มีริบบิ้นยาว 3 เมตร ราคาเมตรละ 13 บาท","ผูกกล่องของขวัญ 3 ใบ ใช้ 11/12 เมตร, 1/8 เมตร, 2/7 เมตร"],"context":[],"steps":[{"kind":"choice","prompt":"ข้อมูลใดไม่จำเป็นต่อการหาความยาวริบบิ้นที่เหลือ","skill":"analysis","points":5,"hints":[],"solution":["คำถามถามความยาว ไม่เกี่ยวกับราคา"],"options":[{"text":"ราคาริบบิ้นเมตรละ 13 บาท","ok":true,"why":""},{"text":"ความยาวที่ใช้ผูกกล่องแต่ละใบ","ok":false,"why":"ต้องใช้หาความยาวที่ใช้ไปทั้งหมด"},{"text":"ความยาวริบบิ้นที่มี 3 เมตร","ok":false,"why":"ต้องใช้ความยาวที่มีเป็นตัวตั้ง"}],"answer":0},{"kind":"fraction","prompt":"ใช้ริบบิ้นไปทั้งหมดกี่เมตร","skill":"calculation","points":10,"hints":["ทำตัวส่วนให้เท่ากันเป็น 168","154/168 + 21/168 + 48/168"],"solution":["ทำตัวส่วนให้เท่ากันเป็น 168: 11/12 = 154/168, 1/8 = 21/168, 2/7 = 48/168","บวกตัวเศษ: 154 + 21 + 48 = 223 จึงได้ 223/168 = 1 55/168 เมตร"],"answer":{"n":223,"d":168},"unit":"เมตร","mistakes":[{"value":{"n":14,"d":27},"why":"บวกตัวส่วนเข้าด้วยกันไม่ได้ ต้องทำตัวส่วนให้เท่ากันก่อน"}]},{"kind":"fraction","prompt":"เหลือริบบิ้นกี่เมตร","skill":"final","points":10,"hints":["3 − 1 55/168","3 = 504/168"],"solution":["3 − 1 55/168 = 504/168 − 223/168 = 1 113/168 เมตร"],"answer":{"n":281,"d":168},"unit":"เมตร"},{"kind":"choice","prompt":"ต้องเก็บริบบิ้นอย่างน้อย 1/2 เมตรไว้ผูกโบว์ใหญ่ ริบบิ้นที่เหลือพอหรือไม่","skill":"final","points":10,"hints":[],"solution":["เทียบ 1 113/168 กับ 1/2 โดยทำตัวส่วนเป็น 168"],"options":[{"text":"พอ","ok":true,"why":"1 113/168 = 281/168 น้อยกว่า 1/2 = 84/168"},{"text":"ไม่พอ","ok":false,"why":"1 113/168 = 281/168 ไม่น้อยกว่า 1/2 = 84/168"}],"answer":0,"keepOrder":true}]}', 'challenge', 30),
('math_fraction_quest', 'ตรวจการบ้านเพื่อน', '{"icon":"📝","story":["พลอยคิดว่า 5/9 + 5/8 = 10/17 โดยบวกตัวเศษกับตัวเศษ และตัวส่วนกับตัวส่วน"],"context":[],"steps":[{"kind":"choice","prompt":"วิธีของพลอยถูกหรือไม่","skill":"planning","points":10,"hints":[],"solution":["เศษส่วนบวกกันได้เมื่อแบ่งเป็นส่วนขนาดเท่ากัน จึงต้องทำตัวส่วนให้เท่ากันก่อน"],"options":[{"text":"ถูก ถ้าตัดทอนเป็นเศษส่วนอย่างต่ำก่อน","ok":false,"why":"การตัดทอนไม่ช่วย เพราะการบวกตัวส่วนผิดตั้งแต่ต้น"},{"text":"ถูก เพราะบวกทั้งตัวเศษและตัวส่วนครบแล้ว","ok":false,"why":"ลองเช็ก: 1/2 + 1/2 ต้องได้ 1 แต่วิธีนี้ได้ 2/4 = 1/2"},{"text":"ผิด เพราะต้องทำตัวส่วนให้เท่ากันก่อน แล้วบวกเฉพาะตัวเศษ","ok":true,"why":""}],"answer":2},{"kind":"fraction","prompt":"คำตอบที่ถูกต้องของ 5/9 + 5/8 คือเท่าไร","skill":"calculation","points":10,"hints":["หา ค.ร.น. ของ 9 และ 8","40/72 + 45/72"],"solution":["ค.ร.น. ของ 9 และ 8 คือ 72","5/9 + 5/8 = 40/72 + 45/72 = 1 13/72"],"answer":{"n":85,"d":72},"mistakes":[{"value":{"n":10,"d":17},"why":"นี่คือคำตอบที่ผิดแบบเดียวกับเพื่อน"}]},{"kind":"choice","prompt":"ตรวจด้วยการประมาณ: ผลบวกที่ถูกต้องต้องมากกว่า 5/8 หรือไม่","skill":"analysis","points":5,"hints":[],"solution":["10/17 ไม่มากกว่า 5/8 จึงเป็นไปไม่ได้"],"options":[{"text":"ต้องมากกว่า เพราะบวกจำนวนที่มากกว่า 0 เข้าไป และคำตอบของพลอยไม่มากกว่า จึงผิดแน่นอน","ok":true,"why":""},{"text":"ไม่จำเป็นต้องมากกว่า","ok":false,"why":"การบวกจำนวนบวกเพิ่มเข้าไป ผลลัพธ์ต้องมากกว่าตัวตั้งเสมอ"}],"answer":0,"keepOrder":true},{"kind":"fraction","prompt":"คำตอบของพลอยน้อยกว่าคำตอบที่ถูกอยู่เท่าไร","skill":"final","points":10,"hints":["1 13/72 − 10/17"],"solution":["ค.ร.น. ของ 72 และ 17 คือ 1224","1 13/72 − 10/17 = 1445/1224 − 720/1224 = 725/1224"],"answer":{"n":725,"d":1224}}]}', 'challenge', 31),
('math_fraction_quest', 'สองสูตรขนมปัง', '{"icon":"🥖","story":["สูตร A ใช้แป้งสาลี 5/12 ถ้วย และแป้งข้าว 5/6 ถ้วย","สูตร B ใช้แป้งสาลี 1 ถ้วย และแป้งข้าว 5/7 ถ้วย","ทั้งสองสูตรอบที่ 180 องศาเซลเซียส นาน 25 นาที"],"context":[],"steps":[{"kind":"fraction","prompt":"สูตร A ใช้แป้งรวมกี่ถ้วย","skill":"calculation","points":10,"hints":["หา ค.ร.น. ของ 12 และ 6"],"solution":["ค.ร.น. ของ 12 และ 6 คือ 12","5/12 + 5/6 = 5/12 + 10/12 = 1 1/4"],"answer":{"n":5,"d":4},"unit":"ถ้วย"},{"kind":"fraction","prompt":"สูตร B ใช้แป้งรวมกี่ถ้วย","skill":"calculation","points":10,"hints":["1 = 7/7"],"solution":["1 + 5/7 = 1 5/7 ถ้วย"],"answer":{"n":12,"d":7},"unit":"ถ้วย"},{"kind":"choice","prompt":"สูตรใดใช้แป้งน้อยกว่า","skill":"analysis","points":10,"hints":[],"solution":["1 1/4 < 1 5/7"],"options":[{"text":"สูตร A","ok":true,"why":"1 1/4 กับ 1 5/7 ทำตัวส่วนให้เท่ากันแล้วเทียบ"},{"text":"สูตร B","ok":false,"why":"1 1/4 กับ 1 5/7 ทำตัวส่วนให้เท่ากันแล้วเทียบ"}],"answer":0,"keepOrder":true},{"kind":"fraction","prompt":"สูตรที่ใช้แป้งน้อยกว่า ประหยัดแป้งได้กี่ถ้วย","skill":"final","points":10,"hints":["นำปริมาณที่มากกว่าลบปริมาณที่น้อยกว่า"],"solution":["ค.ร.น. ของ 7 และ 4 คือ 28","1 5/7 − 1 1/4 = 48/28 − 35/28 = 13/28"],"answer":{"n":13,"d":28},"unit":"ถ้วย"}]}', 'challenge', 32),
('math_decimal_shop', 'จ่ายตลาดให้คุณแม่', '{"icon":"🧺","story":["คุณแม่ให้เงิน 70.00 บาท และรายการที่ต้องซื้อ: ปากกา 2 ด้าม, น้ำผลไม้ 2 ขวด"],"context":[{"type":"table","title":"🏷️ ป้ายราคา","head":["สินค้า","ราคา (บาท)","รายละเอียด"],"rows":[["ปากกา (ด้าม)","12.75","หมึกสีน้ำเงิน"],["น้ำผลไม้ (ขวด)","19.50","ขนาด 350 มิลลิลิตร"]]}],"steps":[{"kind":"fixed","prompt":"ซื้อปากกา 2 ด้าม เป็นเงินกี่บาท","skill":"calculation","points":10,"hints":["12.75 × 2"],"solution":["12.75 × 2 = 25.50 บาท"],"answer":2550,"places":2,"unit":"บาท","money":true},{"kind":"fixed","prompt":"ราคารวมของทั้งตะกร้าเป็นเงินกี่บาท","skill":"analysis","points":10,"hints":["หาราคาแต่ละรายการ (ราคา × จำนวน) แล้วบวกกัน","ตั้งจุดทศนิยมให้ตรงกันก่อนบวก"],"solution":["ปากกา: 12.75 × 2 = 25.50","น้ำผลไม้: 19.50 × 2 = 39.00","รวม 25.50 + 39.00 = 64.50 บาท"],"answer":6450,"places":2,"unit":"บาท","money":true},{"kind":"choice","prompt":"มีงบ 70.00 บาท พอซื้อทั้งหมดหรือไม่","skill":"planning","points":10,"hints":[],"solution":["64.50 < 70.00"],"options":[{"text":"พอ","ok":true,"why":"ราคารวม 64.50 มากกว่างบ 70.00"},{"text":"ไม่พอ","ok":false,"why":"ราคารวม 64.50 ไม่เกินงบ 70.00"}],"answer":0,"keepOrder":true},{"kind":"fixed","prompt":"จะได้รับเงินทอนกี่บาท","skill":"final","points":10,"hints":["นำจำนวนที่มากกว่าลบจำนวนที่น้อยกว่า"],"solution":["70.00 − 64.50 = 5.50 บาท (ตั้งจุดทศนิยมให้ตรงกัน)"],"answer":550,"places":2,"unit":"บาท","money":true}]}', 'easy', 1),
('math_decimal_shop', 'โปรโมชันคุ้มจริงไหม', '{"icon":"🏷️","story":["ต้องซื้อนมกล่อง 5 กล่อง สำหรับงานเลี้ยงห้อง","ราคากล่องละ 22.25 บาท หรือโปรโมชันแพ็ก 3 กล่อง ราคา 65.25 บาท"],"context":[{"type":"note","text":"แผน A: ซื้อทีละกล่อง 5 กล่อง · แผน B: ซื้อแพ็ก 3 ให้มากที่สุด ที่ขาดซื้อทีละกล่อง"},{"type":"note","text":"ข้อมูลอื่น: ขนาด 200 มิลลิลิตร และร้านเปิด 08.30 น."}],"steps":[{"kind":"fixed","prompt":"แผน A ต้องจ่ายกี่บาท","skill":"calculation","points":10,"hints":["22.25 × 5"],"solution":["22.25 × 5 = 111.25 บาท"],"answer":11125,"places":2,"unit":"บาท","money":true},{"kind":"number","prompt":"แผน B ซื้อแพ็ก 3 ได้กี่แพ็ก","skill":"planning","points":10,"hints":["5 ÷ 3 เอาเฉพาะส่วนเต็ม"],"solution":["5 ÷ 3 = 1 เศษ 2 จึงซื้อ 1 แพ็ก และซื้อเพิ่มทีละกล่อง 2 กล่อง"],"answer":1,"unit":"แพ็ก"},{"kind":"fixed","prompt":"แผน B ต้องจ่ายกี่บาท","skill":"calculation","points":10,"hints":["ราคาแพ็ก × จำนวนแพ็ก แล้วบวกราคาที่ซื้อเพิ่มทีละชิ้น"],"solution":["65.25 × 1 + 22.25 × 2 = 109.75 บาท"],"answer":10975,"places":2,"unit":"บาท","money":true},{"kind":"choice","prompt":"แผนใดคุ้มกว่า และถูกกว่ากี่บาท","skill":"final","points":15,"hints":[],"solution":["|111.25 − 109.75| = 1.50 บาท แผน B ถูกกว่า"],"options":[{"text":"แผน A ถูกกว่า 1.50 บาท","ok":false,"why":"แผน A 111.25 เทียบแผน B 109.75"},{"text":"แผน B ถูกกว่า 1.50 บาท","ok":true,"why":"แผน A 111.25 เทียบแผน B 109.75"},{"text":"แผน B ถูกกว่า 2.50 บาท","ok":false,"why":"ผลต่างคือ 111.25 กับ 109.75 ลบกัน"},{"text":"โปรโมชันถูกกว่าเสมอ ไม่ต้องคำนวณ","ok":false,"why":"โปรโมชันบางแบบไม่คุ้ม ต้องคำนวณเทียบทุกครั้ง"}],"answer":1,"keepOrder":true}]}', 'easy', 2),
('math_decimal_shop', 'งบจำกัด ซื้อให้ได้มากที่สุด', '{"icon":"🪙","story":["มีเงิน 150.00 บาท ต้องซื้อขนมปัง 1 ถุง","เงินที่เหลือทั้งหมดจะซื้อสมุดให้ได้มากที่สุด"],"context":[{"type":"table","title":"🏷️ ป้ายราคา","head":["สินค้า","ราคา (บาท)","รายละเอียด"],"rows":[["ขนมปัง (ถุง)","44.00","หนัก 300 กรัม"],["สมุด (เล่ม)","38.25","มี 60 แผ่น"]]}],"steps":[{"kind":"fixed","prompt":"ซื้อขนมปังแล้วเหลือเงินกี่บาท","skill":"calculation","points":10,"hints":["ตั้งจุดทศนิยมให้ตรงกันแล้วลบ"],"solution":["150.00 − 44.00 = 106.00 บาท (ตั้งจุดทศนิยมให้ตรงกัน)"],"answer":10600,"places":2,"unit":"บาท","money":true},{"kind":"number","prompt":"ซื้อสมุดได้มากที่สุดกี่เล่ม","skill":"planning","points":15,"hints":["ลองคูณ 38.25 กับจำนวนต่าง ๆ ให้ใกล้ 106.00 ที่สุดแต่ไม่เกิน"],"solution":["38.25 × 2 = 76.50 ไม่เกิน 106.00","38.25 × 3 = 114.75 เกินงบ"],"answer":2,"unit":"เล่ม","mistakes":[{"value":3,"why":"3 เล่ม ต้องจ่าย 114.75 บาท เกินเงินที่เหลือ"}]},{"kind":"fixed","prompt":"หลังซื้อทั้งหมดจะเหลือเงินกี่บาท","skill":"final","points":10,"hints":["เงินที่เหลือหลังซื้อสินค้าหลัก ลบด้วยค่าสินค้าชิ้นเล็กทั้งหมด"],"solution":["106.00 − 76.50 = 29.50 บาท (ตั้งจุดทศนิยมให้ตรงกัน)"],"answer":2950,"places":2,"unit":"บาท","money":true}]}', 'easy', 3),
('math_decimal_shop', 'จ่ายตลาดให้คุณแม่', '{"icon":"🧺","story":["คุณแม่ให้เงิน 70.00 บาท และรายการที่ต้องซื้อ: นมกล่อง 1 กล่อง, น้ำผลไม้ 2 ขวด"],"context":[{"type":"table","title":"🏷️ ป้ายราคา","head":["สินค้า","ราคา (บาท)","รายละเอียด"],"rows":[["นมกล่อง (กล่อง)","19.00","ขนาด 200 มิลลิลิตร"],["น้ำผลไม้ (ขวด)","17.75","ขนาด 350 มิลลิลิตร"]]}],"steps":[{"kind":"fixed","prompt":"ซื้อน้ำผลไม้ 2 ขวด เป็นเงินกี่บาท","skill":"calculation","points":10,"hints":["17.75 × 2"],"solution":["17.75 × 2 = 35.50 บาท"],"answer":3550,"places":2,"unit":"บาท","money":true},{"kind":"fixed","prompt":"ราคารวมของทั้งตะกร้าเป็นเงินกี่บาท","skill":"analysis","points":10,"hints":["หาราคาแต่ละรายการ (ราคา × จำนวน) แล้วบวกกัน","ตั้งจุดทศนิยมให้ตรงกันก่อนบวก"],"solution":["นมกล่อง: 19.00 × 1 = 19.00","น้ำผลไม้: 17.75 × 2 = 35.50","รวม 19.00 + 35.50 = 54.50 บาท"],"answer":5450,"places":2,"unit":"บาท","money":true},{"kind":"choice","prompt":"มีงบ 70.00 บาท พอซื้อทั้งหมดหรือไม่","skill":"planning","points":10,"hints":[],"solution":["54.50 < 70.00"],"options":[{"text":"พอ","ok":true,"why":"ราคารวม 54.50 มากกว่างบ 70.00"},{"text":"ไม่พอ","ok":false,"why":"ราคารวม 54.50 ไม่เกินงบ 70.00"}],"answer":0,"keepOrder":true},{"kind":"fixed","prompt":"จะได้รับเงินทอนกี่บาท","skill":"final","points":10,"hints":["นำจำนวนที่มากกว่าลบจำนวนที่น้อยกว่า"],"solution":["70.00 − 54.50 = 15.50 บาท (ตั้งจุดทศนิยมให้ตรงกัน)"],"answer":1550,"places":2,"unit":"บาท","money":true}]}', 'easy', 4),
